    (615, 'SUB-0615', 'SBM2', 'CAUSAL DE PASE A LA SITUACIÓN DE RETIRO. TIENE LA FINALIDAD DE MANTENER LOS CUADROS DE PERSONAL EN FUNCIÓN A LAS NECESIDADES INSTITUCIONALES', 'RENOVACIÓN DE CUADROS.', 'ART. 3 Num. 26', '181482'),
    (616, 'SUB-0616', 'SBM2', 'CORRESPONDE A UNA JERARQUÍA:', 'SUBOFICIALES TÉCNICOS.', 'ART. 13 Num. 3', '181483'),
    (617, 'SUB-0617', 'SBM2', 'EL GRADO SE EJERCE CON RESPONSABILIDAD. A MAYOR GRADO, MAYOR RESPONSABILIDAD. LA RESPONSABILIDAD ES INDELEGABLE; SE REFIERE A', 'ATRIBUTOS Y RESPONSABILIDADES CORRESPONDIENTES AL GRADO DEL PERSONAL POLICIAL', 'ART. 25', '181484'),
    (618, 'SUB-0618', 'SBM2', 'NINGUNA AUTORIDAD JUDICIAL O ADMINISTRATIVA, DISTINTA A LA ESTABLECIDA EN EL PRESENTE DECRETO LEGISLATIVO, ESTÁ FACULTADA A DISPONER EL OTORGAMIENTO DE ATRIBUTOS AL PERSONAL POLICIAL; SE REFIERE A:', 'ATRIBUTOS Y RESPONSABILIDADES CORRESPONDIENTES AL GRADO DEL PERSONAL POLICIAL. Decreto Legislativo 1149', 'ART. 25', '181485'),
    (619, 'SUB-0619', 'SBM2', 'ORGANIZACION, NIVELES, CATEGORIAS: SUBOFICIALES DE ARMAS, JERARQUIAS, LOS SUBOFICIALES SUPERIORES DE ARMAS SE CLASIFICAN EN:', 'SUBOFICIAL SUPERIOR Y SUBOFICIAL BRIGADIER.', 'ART. 13 Num. 3 Inc. 1', '181486'),
    (620, 'SUB-0620', 'SBM2', 'ORGANIZACION, NIVELES, CATEGORIAS: OFICIALES DE ARMAS, JERARQUIAS, OFICIALES SUBALTERNOS SE CLASIFICAN EN:', 'CAPITAN, TENIENTE Y ALFEREZ.', 'ART. 13 Num. 1 Lit. C', '181487'),
    (621, 'SUB-0621', 'SBM2', 'SON REQUISITOS PARA LA ASIMILACIÓN LO SIGUIENTE:', 'PARA SUBOFICIAL DE SERVICIOS: TÍTULO TÉCNICO DE INSTITUTOS SUPERIORES, EN CUYO CASO ES ASIMILADO EN EL GRADO DE SUBOFICIAL DE TERCERA.', 'ART. 19 Num. 1 Lit. 2', '181489'),
    (622, 'SUB-0622', 'SBM2', 'SU APROBACIÓN CONSTITUYE REQUISITO PARA CONTINUAR EN LA CONDICIÓN DE ASIMILADO.', 'CURSO DE ADAPTACIÓN INSTITUCIONAL.', 'ART. 19 Num. 4', '181490'),
    (623, 'SUB-0623', 'SBM2', 'ASIMILACIÓN: EL CURSO DE ADAPTACIÓN INSTITUCIONAL SE DESARROLLA DURANTE LOS:', 'TRES (3) PRIMEROS MESES DEL PERÍODO DE ASIMILACIÓN CON CARÁCTER OBLIGATORIO', 'ART. 19 Num. 4', '181491'),
    (624, 'SUB-0624', 'SBM2', 'QUE DECRETO LEGISLATIVO REGULA LA LEY DE LA CARRERA Y SITUACIÓN DEL PERSONAL POLICÍA NACIONAL DEL PERÚ.', 'DECRETO LEGISLATIVO 1149.', 'DECRETO LEGISLATIVO N°1149', '181492'),
    (625, 'SUB-0625', 'SBM2', 'DECRETO LEGISLATIVO 1149 QUE REGULA LA LEY DE LA CARRERA Y SITUACIÓN DEL PERSONAL POLICÍA NACIONAL DEL PERÚ FUE PROMULGADO POR EL PRESIDENTE DE LA REPÚBLICA EL:', '10 DE DICIEMBRE DEL 2012.', 'DECRETO LEGISLATIVO N°1149', '181493'),
    (626, 'SUB-0626', 'SBM2', 'DECRETO LEGISLATIVO 1149 FUE PROMULGADO EL 10 DE DICIEMBRE DEL 2012 POR EL PRESIDENTE CONSTITUCIONAL DE LA REPÚBLICA', 'OLLANTA HUMALA TASSO.', 'DECRETO LEGISLATIVO N°1149', '181494'),
    (627, 'SUB-0627', 'SBM2', 'EL DECRETO LEGISLATIVO 1149 QUE REGULA LA LEY DE LA CARRERA Y SITUACIÓN DEL PERSONAL POLICÍA NACIONAL DEL PERÚ FUE PROMULGADO EN EL AÑO:', '2012', 'DECRETO LEGISLATIVO 1149', '181495'),
    (628, 'SUB-0628', 'SBM2', 'PRECEDENCIA EN EL GRADO:', 'PARA EL PERSONAL INCORPORADO POR ASIMILACIÓN, LA ANTIGÜEDAD SE DETERMINA EN ATENCIÓN AL ORDEN DE MÉRITO DE SU INCORPORACIÓN.', 'ART. 24 Num. 6', '181496'),
    (629, 'SUB-0629', 'SBM2', 'PARA EFECTOS DE LA PRESENTE NORMA, SE ESTABLECEN LAS SIGUIENTES DEFINICIONES: ASCENSO:', 'TIENE POR FINALIDAD GARANTIZAR LA LÍNEA DE CARRERA POLICIAL, COMO RESULTADO OBJETIVO DEL PROCESO DE EVALUACIÓN DE LOS MÉRITOS Y DEMÉRITOS REGISTRADOS DURANTE LA CARRERA.', 'ART. 3 Num. 2', '181501'),
    (630, 'SUB-0630', 'SBM2', 'DE LOS PRINCIPIOS RECTORES: PRINCIPIO DE TRANSPARENCIA:', 'SE FUNDAMENTA EN LA PUBLICIDAD DE TODOS LOS PROCESOS RELACIONADOS A LA PRESENTE NORMA.', 'ART. 4 Num. 5', '181502'),
    (631, 'SUB-0631', 'SBM2', 'ES UNA FUNCIÓN DE LA INSPECTORÍA GENERAL DE LA POLICÍA NACIONAL DEL PERÚ, GARANTIZAR EL CUMPLIMIENTO DE LA PRESENTACIÓN DE LAS DECLARACIONES JURADAS DE INGRESOS, BIENES Y RENTAS DEL PERSONAL POLICIAL A NIVEL NACIONAL, DE MANERA:.', 'OPORTUNA.', 'REGLAMENTO ART. 11', '181591'),
    (632, 'SUB-0632', 'SBM2', 'QUE NORMA APRUEBA LAS HERRAMIENTAS PARA LA LUCHA CONTRA LA CORRUPCION EN EL SECTOR INTERIOR:.', 'EL REGLAMENTO DEL DECRETO LEGISLATIVO 1291', 'ART. 5', '181592'),
    (633, 'SUB-0633', 'SBM2', 'LA IDENTIDAD DE LOS ................. SE MANTIENE EN RESERVA HASTA EL TÉRMINO DE LA EJECUCIÓN DE LA PRUEBA:.', 'COMISIONADOS DE INTEGRIDAD.', 'REGLAMENTO ART. 31', '181594'),
    (634, 'SUB-0634', 'SBM2', 'LA APLICACIÓN DE LAS PRUEBAS DE CONTROL Y CONFIANZA SE REALIZA A TRAVÉS DE PERSONAL ESPECIALIZADO DEL SECTOR O: MARQUE LA RESPUESTA CORRECTA:.', 'CONSULTORES EXTERNOS.', 'REGLAMENTO ART. 20', '181595'),
    (635, 'SUB-0635', 'SBM2', 'EL PERSONAL DE LOS DIFERENTES ORGANOS Y UNIDADES DEL SECTOR INTERIOR, INCLUYENDO A LA PNP, QUE APLIQUE LAS HERRAMIENTAS PARA LA LUCHA CONTRA LA CORRUPCION DISPUESTAS EN DL. N° 1291, ESTAN EN LA OBLIGACION A QUE EL USO DE LA INFORMACIÓN OBTENIDA SE LIMITA ÚNICA Y EXCLUSIVAMENTE PARA FINES INSTITUCIONALES. NOS REFERIMOS A:.', 'RESTRICCIONES Y RESERVAS.', 'REGLAMENTO ART. 3', '181596'),
    (636, 'SUB-0636', 'SBM2', 'LA PRUEBA DE CONTROL Y CONFIANZA, SE CARACTERIZA POR LO SIGUIENTE: MARQUE LA RESPUESTA CORRECTA:', 'EL SOMETIMIENTO A LA PRUEBA ES VOLUNTARIO.', 'ART. 9', '181597'),
    (637, 'SUB-0637', 'SBM2', 'DE CONFORMIDAD AL DECRETO LEGISLATIVO 1291, EN LA RENDICION DE CUENTAS DEL CIUDADANO; LA RESPONSABILIDAD DEL JEFE DE LAS DIRECCIONES ESPECIALIZADAS O FRENTES POLICIALES ES:', 'SUPERVISAR EL CUMPLIMIENTO DE LAS RENDICIONES DE CUENTAS.', 'ART. 10', '181598'),
    (638, 'SUB-0638', 'SBM2', 'REALIZAR EL ANÁLISIS, VERIFICACIÓN Y SEGUIMIENTO DE MANERA ALEATORIA DE LA INFORMACIÓN CONTENIDA EN LAS DECLARACIONES JURADAS CORRESPONDIENTES PREVIAMENTE REGISTRADAS EN EL "SISTEMA DE DECLARACIONES JURADAS DE INGRESOS, BIENES Y RENTAS DEL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ", ES UNA FUNCIÓN DE:.', 'LA OFICINA DE CONTROL, CUMPLIMIENTO Y CONFIANZA DE LA OGII.', 'REGLAMENTO ART. 10', '181599'),
    (639, 'SUB-0639', 'SBM2', 'ES LA OFICINA RESPONSABLE DE LA APLICACION DE LA PRUEBA DE INTEGRIDAD: ESTA COORDINA LA EJECUCIÓN DE LAS PRUEBAS DE INTEGRIDAD CON LAS AUTORIDADES DE LOS DIFERENTES ÓRGANOS DEL ESTADO QUE FUERE NECESARIO. MARQUE LA RESPUESTA CORRECTA:', 'LA OFICINA GENERAL DE INTEGRIDAD INSTITUCIONAL.', 'REGLAMENTO ART. 27', '181600'),
    (640, 'SUB-0640', 'SBM2', 'EN EL TITULO DE RENDICION DE CUENTAS AL CIUDADNO Y PRUEBA DE INTEGRIDAD: UNA CARACTERÍSTICA DE LA PRUEBA DE INTEGRIDAD SEÑALA: QUE SE GUARDARÁ RESERVA DEL PERSONAL QUE SE DESEMPEÑA COMO:', 'COMISIONADO DE INTEGRIDAD.', 'ART. 16', '181601'),
    (641, 'SUB-0641', 'SBM2', '¿QUE PRUEBA PERMITE VERIFICAR SU DISPOSICIÓN AL CUMPLIMIENTO DE ESTÁNDARES MÍNIMOS DE ÉTICA, INTEGRIDAD Y HONESTIDAD? AL PERSONAL POLICIAL EN SITUACION DE ACTIVIDAD Y AL PERSONAL CIVIL DEL SECTOR INTERIOR.', 'LA PRUEBA DE INTEGRIDAD.', 'ART. 11', '181602'),
    (642, 'SUB-0642', 'SBM2', 'REQUERIR DOCUMENTACIÓN QUE CONSIDERE NECESARIA A LOS DECLARANTES CUANDO EXISTAN INCONSISTENCIAS EN LA INFORMACIÓN REGISTRADA EN EL SISTEMA, ES UNA FUNCIÓN DE:.', 'LA OFICINA DE CONTROL, CUMPLIMIENTO Y CONFIANZA.', 'REGLAMENTO ART. 10', '181603'),
    (643, 'SUB-0643', 'SBM2', 'ES AQUELLA PRUEBA MEDIANTE LA CUAL SE VERIFICA LA CONGRUENCIA ENTRE LA INFORMACIÓN PATRIMONIAL PROPORCIONADA POR PERSONAL CIVIL O POLICIAL Y EL ENTORNO SOCIAL, ECONÓMICO Y LABORAL EN EL QUE SE DESARROLLA:.', 'LA PRUEBA DE ENTORNO SOCIAL Y SITUACIÓN PATRIMONIAL.', 'REGLAMENTO ART. 16', '181604'),
    (644, 'SUB-0644', 'SBM2', 'SEGÚN EL ARTÍCULO 18 DEL DECRETO LEGISLATIUVO 1291, LA ESPECIALIDAD DE CONTROL ADMINISTRATIVO DISCIPLINARIO, TIENE POR OBJETIVO QUE LOS ÓRGANOS Y UNIDADES ORGÁNICAS DEL SISTEMA DISCIPLINARIO POLICIAL CUENTEN CON:', 'PERSONAL POLICIAL ALTAMENTE CALIFICADO Y CON EL PERFIL IDÓNEO.', 'ART. 18', '181605'),
    (645, 'SUB-0645', 'SBM2', 'DE CONFORMIDAD AL DECRETO LEGISLATIVO 1291, DDJJ DEL PERSONAL POLICIAL: "LOS OFICIALES Y SUBOFICIALES DE LA POLICÍA NACIONAL DEL PERÚ ESTÁN OBLIGADOS A:.....', 'PRESENTAR DECLARACIÓN JURADA DE INGRESOS, BIENES Y RENTAS.', 'ART. 2', '181606'),
    (646, 'SUB-0646', 'SBM2', 'SEGÚN EL DECRETO LEGISLATIVO 1291: ES UNA CARACTERISTICA DE LA PRUEBA DE INTEGRIDAD: LAS SITUACIONES QUE SE PLANTEAN EN LA PRUEBA DE INTEGRIDAD NO SERÁN:......', 'INVASIVAS A LA PRIVACIDAD', 'ART. 16', '181607'),
    (647, 'SUB-0647', 'SBM2', 'SEGUN EL REGLAMENTO DEL D.L. 1291, EN EL CONTENIDO DE LA PRUEBA DE CONTROL Y CONFIANZA: ¿EN QUE CASO ESTA PRUEBA PUEDE ESTAR REFERIDA A LA VIDA PERSONAL O PRIVADA DEL PERSONAL O SU FAMILIA, NI ATENTAR CONTRA SU HONOR, DIGNIDAD Y DDHH O PRINCIPIOS CONSTITUCIONALES?.', 'EN NINGÚN CASO.', 'REGLAMENTO ART. 21', '181608'),
    (648, 'SUB-0648', 'SBM2', 'ESTARÁ REFERIDA AL INCREMENTO O DISMINUCIÓN DE LA CRIMINALIDAD DENTRO DE LA JURISDICCIÓN, ASÍ COMO A LAS DIFICULTADES CON QUE PUEDA HABERSE ENCONTRADO LA POLICÍA NACIONAL DEL PERÚ EN LA EJECUCIÓN DE SUS ACTIVIDADES, Y A LOS LOGROS Y METAS PLANTEADOS Y ALCANZADOS O EN DESARROLLO, NOS REFERIMOS A:.', 'OBLIGACION DE RENDIR CUENTAS, OPORTUNIDAD DE RENDICION Y CONTENIDO', 'REGLAMENTO ART. 24', '181609'),
    (649, 'SUB-0649', 'SBM2', 'EL PERSONAL PNP QUE TENGA COMO FUNCION LA APLICACION DE LAS HERRAMIENTAS PARA LA LUCHA CONTRA LA CORRUPCION ESTABLECIDAS EN EL D.L N° 1291; ESTÁ OBLIGADO A MANTENER ESTRICTA RESERVA Y CONFIDENCIALIDAD DE TODA LA INFORMACIÓN OBTENIDA COMO RESULTADO DE LA APLICACIÓN DE LAS HERRAMIENTAS. NOS REFERIMOS A:.', 'ART. 3 RESTRICCIONES Y RESERVAS.', 'REGLAMENTO ART. 3', '181610'),
    (650, 'SUB-0650', 'SBM2', 'ES UNA PRUEBA EN LA QUE CONSISTE EN PLANTEAR SITUACIONES SIMILARES A LAS QUE UN EFECTIVO POLICIAL O SERVIDOR CIVIL PODRÁ ENFRENTAR COMO PARTE DE LAS ACTIVIDADES PROPIAS DE SU FUNCIÓN:.', 'LA PRUEBA DE INTEGRIDAD.', 'ART. 11', '181611'),
    (651, 'SUB-0651', 'SBM2', 'LA PRUEBA DE INTEGRIDAD CONSISTE EN PLANTEAR SITUACIONES SIMILARES A LAS QUE UN EFECTIVO POLICIAL O SERVIDOR CIVIL PODRA ENFRENTAR COMO PARTE DE:.', 'LAS ACTIVIDADES PROPIAS DE SU FUNCIÓN.', 'ART. 11', '181612'),
    (652, 'SUB-0652', 'SBM2', '¿QUIEN ES RESPONSABLE DE GARANTIZAR QUE EL PERSONAL POLICIAL A NIVEL NACIONAL REALICE EL REGISTRO DE SUS DECLARACIONES JURADAS DE INGRESOS, BIENES Y RENTAS?.', 'LA INSPECTORÍA GENERAL DE LA POLICÍA NACIONAL DEL PERÚ.', 'ART. 4', '181613'),
    (653, 'SUB-0653', 'SBM2', 'EN LA RESTRICCIONES Y RESERVAS DEL REGLAMENTO DEL D.L.N° 1291; LA INFORMACIÓN OBTENIDA DE LAS PRUEBAS DE CONTROL Y CONFIANZA SE CODIFICA BAJO RESPONSABILIDAD DE LA:..........', 'OFICINA DE CONTROL, CUMPLIMIENTO Y CONFIANZA', 'REGLAMENTO ART. 22', '181614'),
    (654, 'SUB-0654', 'SBM2', 'EL DIRECTOR GENERAL DE LA OFICINA GENERAL DE INTEGRIDAD INSTITUCIONAL DETERMINARÁ LA POLÍTICA PARA LA APLICACION DE LA PRUEBA DE CONTROL Y CONFIANZA A LOS:.......', 'FUNCIONARIOS Y/O SERVIDORES CIVILES DE LAS OFICINAS A SU CARGO Y A LA INSPECTORÍA GENERAL DE LA POLICÍA NACIONAL DEL PERÚ.', 'ART. 8', '181615'),
    (655, 'SUB-0655', 'SBM2', '¿SEÑALE CUAL ES LA FUNCIÓN DE LA INSPECTORÍA GENERAL DE LA POLICÍA NACIONAL DEL PERÚ, RESPECTO A LAS DECLARACIONES JURADAS DE INGRESOS, BIENES Y RENTAS DEL PERSONAL POLICIAL?.', 'GARANTIZAR EL CUMPLIMIENTO DE LA PRESENTACIÓN DE LAS DECLARACIONES JURADAS DE INGRESOS, BIENES Y RENTAS DEL PERSONAL POLICIAL A NIVEL NACIONAL DE MANERA OPORTUNA.', 'REGLAMENTO ART. 11', '181616'),
    (656, 'SUB-0656', 'SBM2', 'EL SISTEMA DE DECLARACIONES JURADAS DE INGRESOS, BIENES Y RENTAS DEL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ, ES UN INSTRUMENTO MEDIANTE EL CUAL SE REALIZA:.', 'EL REGISTRO Y PROCESAMIENTO DE LAS DECLARACIONES JURADAS QUE PRESENTA EL PERSONAL POLICIAL A NIVEL NACIONAL.', 'ART. 3', '181617'),
    (657, 'SUB-0657', 'SBM2', 'ES LA PERSONA SELECCIONADA E INSTRUIDA PARA PLANTEAR UNA SITUACION SIMULADA QUE PERMITA EVALUAR LA CONDUCTA ÍNTEGRA, PROBA, HONRADA, INCORRUPTIBLE E INSOBORNABLE DEL PERSONAL POLICIAL O CIVIL DEL SECTOR INTERIOR EN EL CUMPLIMIENTO DE SUS FUNCIONES?', 'EL COMISIONADO DE INTEGRIDAD', 'ART. 13', '181618'),
    (658, 'SUB-0658', 'SBM2', 'CONFORME AL ARTÍCULO 13 DEL DECRETO LEGISLATIVO 1291, EL COMISIONADO DE INTEGRIDAD ES LA PERSONA SELECCIONADA E INSTRUIDA PARA PLANTEAR UNA SITUACIÓN SIMULADA QUE:.', 'PERMITA EVALUAR LA CONDUCTA INTEGRA, PROBA, HONRADA, INCORRUPTIBLE E INSOBORNABLE DEL PERSONAL POLICIAL O CIVIL DEL SECTOR INTERIOR', 'ART. 13', '181619'),
    (659, 'SUB-0659', 'SBM2', 'EL PERSONAL POLICIAL QUE EJERZA LA ESPECIALIDAD DE CONTROL ADMINISTRATIVO DISCIPLINARIO TIENE EL SIGUIENTE INCENTIVO:.', 'PERMANENCIA EN LA ESPECIALIDAD HASTA EL TÉRMINO DE LA CARRERA POLICIAL.', 'ART. 19', '181620'),
    (660, 'SUB-0660', 'SBM2', '¿QUIEN SE ENCARGA DE ELABORAR LAS DIRECTIVAS QUE ESTABLECEN LOS PROTOCOLOS, PROCEDIMIENTOS, METAS, OBJETIVOS Y PLAZOS PARA LA APLICACIÓN DE LAS PRUEBAS?.', 'LA OFICINA DE CONTROL, CUMPLIMIENTO Y CONFIANZA.', 'REGLAMENTO ART. 20', '181621'),
    (661, 'SUB-0661', 'SBM2', 'UNA CARACTERISTICA DE LA PRUEBA DE INTEGRIDAD SEÑALA QUE, SI COMO RESULTADO DE LA PRUEBA SE PRESENTA UNA CONDUCTA TIPIFICADA COMO INFRACCIÓN DISCIPLINARIA O ILÍCITO PENAL, SE PROCEDERÁ:.', 'DE ACUERDO A LO ESTABLECIDO EN LA NORMATIVIDAD VIGENTE.', 'ART. 16', '181622'),
    (662, 'SUB-0662', 'SBM2', '¿QUIEN DETERMINARA LA POLITICA PARA LA APLICACIÓN DE LA PRUEBA DE CONTROL Y CONFIANZA A LOS FUNCIONARIOS, SERVIDORES CIVILES O POLICIALES DEL SECTOR INTERIOR?.', 'EL MINISTRO DEL INTERIOR.', 'ART. 8', '181623'),
    (663, 'SUB-0663', 'SBM2', 'EN LOS TIPOS DE PRUEBAS DE CONTROL Y CONFIANZA, LA EJECUCIÓN DE LA PRUEBA DE CONTROL Y CONFIANZA ES. ................. DE LAS PRUEBAS DE DESCARTE TOXICOLÓGICO O DE ALCOHOLEMIA QUE LA OFICINA DE CONTROL, CUMPLIMIENTO Y CONFIANZA DE LA OFICINA GENERAL DE INTEGRIDAD INSTITUCIONAL O LA INSPECTORÍA GENERAL DE LA POLICÍA NACIONAL DEL PERÚ PUEDEN REALIZAR:.', 'INDEPENDIENTE.', 'REGLAMENTO ART. 14', '181624'),
    (664, 'SUB-0664', 'SBM2', 'FINALIDAD DE LA PRUEBA DE INTEGRIDAD; LA PRUEBA DE INTEGRIDAD BUSCA DETERMINAR SI EL PERSONAL POLICIAL EN ACTIVIDAD O SERVIDOR CIVIL DEL SECTOR INTERIOR TIENE UNA CONDUCTA INTEGRA, HONRADA, INCORUPTIBLE, INSOBORNABLE Y ............ DEL PERSONAL PNP.', 'PROBA.', 'ART. 12', '181625'),
    (665, 'SUB-0665', 'SBM2', 'PONER EN CONOCIMIENTO DE LA AUTORIDAD CORRESPONDIENTE PARA LAS ACCIONES DE SU COMPETENCIA, AQUELLOS CASOS, EN QUE EL CONTENIDO DE LO DECLARADO, SE EVIDENCIEN HECHOS QUE HAGAN PRESUMIR O CONSTITUYAN INFRACCIÓN DISCIPLINARIA; ES UNA FUNCIÓN DE:.', 'LA OFICINA DE CONTROL, CUMPLIMIENTO Y CONFIANZA.', 'REGLAMENTO ART. 10', '181626'),
    (666, 'SUB-0666', 'SBM2', 'TIENE CARÁCTER ALEATORIO Y DE APLICACIÓN A NIVEL NACIONAL, ES UNA CARACTERISTICA DE:.', 'LA PRUEBA DE INTEGRIDAD.', 'ART. 16', '181627'),
    (667, 'SUB-0667', 'SBM2', 'EFECTUARÁ LA PRUEBA DE INTEGRIDAD AL PERSONAL QUE FORMA PARTE DEL SISTEMA DISCIPLINARIO POLICIAL:.', 'LA OFICINA GENERAL DE INTEGRIDAD INSTITUCIONAL', 'ART. 14', '181628'),
    (668, 'SUB-0668', 'SBM2', 'LA ADMINISTRACIÓN DEL SISTEMA DE DECLARACIONES JURADAS DE INGRESOS, BIENES Y RENTAS DEL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ ESTARÁ A CARGO DEL:.', 'MINISTERIO DEL INTERIOR.', 'ART. 3', '181629'),
    (669, 'SUB-0669', 'SBM2', 'EL SOMETIMIENTO A LA PRUEBA DE CONTROL Y CONFIANZA ES ...............Y DEBERA CONTAR CON LA AUTORIZACION EXPRESA DEL PERSONAL SELECCIONADO PARA PASAR LA MISMA.', 'VOLUNTARIO.', 'ART. 7', '181630'),
    (670, 'SUB-0670', 'SBM2', '¿QUE NORMA TIENE POR OBJETO REGULAR Y DESARROLLAR EL DECRETO LEGISLATIVO 1291, DECRETO LEGISLATIVO QUE APRUEBA HERRAMIENTAS PARA LA LUCHA CONTRA LA CORRUPCIÓN EN EL SECTOR INTERIOR?.', 'EL DECRETO SUPREMO 013-2017–IN.', 'REGLAMENTO ART. 1', '181631'),
    (671, 'SUB-0671', 'SBM2', 'SE ELABORA EN BASE A LA ACTIVIDAD FUNCIONAL DEL ÓRGANO, UNIDAD O DEPENDENCIA EN LA CUAL EL SERVIDOR CIVIL O POLICIAL LABORA O PRESTA SERVICIOS: MARQUE LA RESPUESTA CORRECTA:.', 'EL CONTENIDO DE LA PRUEBA DE CONTROL Y CONFIANZA.', 'REGLAMENTO ART. 21', '181632'),
    (672, 'SUB-0672', 'SBM2', 'ES UNA CARACTERISTICA DE LA PRUEBA DE CONTROL Y CONFIANZA:.', 'NO SE AFECTA LA INTIMIDAD PERSONAL.', 'ART. 9', '181633'),
    (673, 'SUB-0673', 'SBM2', 'EL DECRETO LEGISLATIVO 1291, TIENE COMO OBJETO CREAR HERRAMIENTAS EFECTIVAS POARA LA LUCHA CONTRA LA CORRUPCION EN EL SECTOR INTERIOR, CON LA FINALIDAD DE LOGRAR UNA:', 'GESTIÓN TRANSPARENTE Y CONFIABLE PARA LA CIUDADANÍA.', 'ART. 1', '181634'),
    (674, 'SUB-0674', 'SBM2', 'DE CONFORMIDAD AL DECRETO LEGISLATIVO 1291, QUE OFICINA EFECTUARÁ LA PRUEBA DE INTEGRIDAD AL PERSONAL QUE FORMA PARTE DEL SISTEMA DISCIPLINARIO POLICIAL Y AL PERSONAL POLICIAL Y CIVIL DE OTRAS ÁREAS DEL SECTOR INTERIOR, NOS REFERIMOS A:.', 'LA OFICINA GENERAL DE INTEGRIDAD INSTITUCIONAL.', 'ART. 14', '181635'),
    (675, 'SUB-0675', 'SBM2', 'LA PRUEBA DE CONTROL Y CONFIANZA SE EFECTÚA MEDIANTE LA UTILIZACIÓN DEL:.', 'POLÍGRAFO.', 'ART. 7', '181636'),
    (676, 'SUB-0676', 'SBM2', 'DEL ENUNCIADO SIGUIENTE: ¿CUÁL CORRESPONDE A UNA CARACTERÍSTICA DE LA PRUEBA DE INTEGRIDAD SEGÚN EL DECRETO LEGISLATIVO 1291?.', 'LA APLICACIÓN DE LA PRUEBA POR SÍ MISMA NO CONSTITUYE SANCIÓN DISCIPLINARIA.', 'ART. 16', '181637'),
    (677, 'SUB-0677', 'SBM2', 'UNA DE LAS FUNCIONES DE LA OFICINA DE CONTROL, CUMPLIMIENTO Y CONFIANZA; ES DICTAR LOS LINEAMIENTOS PARA:.....', 'GARANTIZAR LA CONFIDENCIALIDAD Y RESERVA DE LA INFORMACIÓN DE LAS DDJJ DE INGRESOS, BIENES Y RENTAS.', 'REGLAMENTO ART. 10', '181638'),
    (678, 'SUB-0678', 'SBM2', 'GESTIONAR A TRAVÉS DE LA OFICINA GENERAL DE INTEGRIDAD INSTITUCIONAL DEL MINISTERIO DEL INTERIOR, LA OBTENCIÓN DE INFORMACIÓN DE OTROS ORGANISMOS O ENTIDADES PÚBLICAS O PRIVADAS, PARA LA VERIFICACIÓN Y CONTRASTE DEL CONTENIDO DE LAS DECLARACIONES JURADAS, ES FUNCIÓN DE:.', 'LA OFICINA DE CONTROL, CUMPLIMIENTO Y CONFIANZA.', 'REGLAMENTO ART. 10', '181639'),
    (679, 'SUB-0679', 'SBM2', 'CONFORME AL DECRETO LEGISLATIVO 1291, LOS BENEFICIOS SEÑALADOS OTORGADOS AL PERSONAL POLICIAL QUE SEA SELECCIONADO PARA INTEGRAR EL:.......', 'SISTEMA DISCIPLINARIO POLICIAL.', 'ART. 19', '181640'),
    (680, 'SUB-0680', 'SBM2', 'SEGÚN EL DECRETO LEGISLATIVO 1291, SOBRE RESULTADO DE LA PRUEBA DE INTEGRIDAD, LOS RESULTADOS DE LA PRUEBA SERÁN REGISTRADOS EN SU:.', 'LEGAJO PERSONAL Y PERFIL ESTADÍSTICO DE LA DIRECCIÓN DE RECURSOS HUMANOS O LA QUE HAGA SUS VECES', 'ART. 15', '181641'),
    (681, 'SUB-0681', 'SBM2', 'SEGÚN EL DECRETO LEGISLATIVO 1291, EN EL RESULTADO DE LA PRUEBA DE INTEGRIDAD, SERÁ REASIGNADO A UN NUEVO CARGO POR NO RESPONDER AL PERFIL DE LA FUNCIÓN ESPECÍFICA A DESARROLLAR U OTRA ACCIÓN ADMINISTRATIVA QUE SE ESTABLEZCA POR LEY. EL PERSONAL QUE:.', 'NO RESPONDA SATISFACTORIAMENTE A LA PRUEBA DE INTEGRIDAD.', 'ART. 15', '181642'),
    (682, 'SUB-0682', 'SBM2', 'EL PERSONAL POLICIAL QUE EJERZA LA ESPECIALIDAD DE CONTROL ADMINISTRATIVO DISCIPLINARIO TIENE EL SIGUIENTE INCENTIVO:.', 'VACANTES EXCLUSIVAS EN LOS PROCESOS DE ASCENSO PARA CUBRIR LAS NECESIDADES DE LA ESPECIALIDAD.', 'ART. 19', '181643'),
    (683, 'SUB-0683', 'SBM2', 'EN LA RENDICION DE CUENTAS AL CIUDADANO; ESTÁN OBLIGADOS A RENDIR CUENTA ANTE SU COMUNIDAD, RESPECTO A SU JURISDICCION, LOS OBJETIVOS PROPUESTOS Y LAS METAS ALCANZADAS:.', 'LAS AUTORIDADES POLICIALES DENTRO SU JURISDICCIÓN.', 'ART. 10', '181645'),
    (684, 'SUB-0684', 'SBM2', '¿EN QUE GRADOS EL PERSONAL POLICIAL PREVIAMENTE SELECCIONADO FORMARÁ PARTE DE LOS ÓRGANOS Y UNIDADES ORGÁNICAS DEL SISTEMA DISCIPLINARIO POLICIAL INSPECTORÍA GENERAL DE LA POLICÍA NACIONAL DEL PERÚ?.', 'MAYOR DE LA POLICÍA NACIONAL DEL PERÚ Y SUBOFICIALES TÉCNICOS', 'ART. 18', '181646'),
    (685, 'SUB-0685', 'SBM2', 'LA APLICACIÓN DE LA PRUEBA DE INTEGRIDAD ESTÁ A CARGO DE LA OFICINA GENERAL DE INTEGRIDAD INSTITUCIONAL, SE REALIZA A TRAVÉS DE UNO O MAS COMISIONADOS DE INTEGRIDAD, Y ES. ........ : MARQUE LA RESPUESTA CORRECTA:.', 'ALEATORIA.', 'REGLAMENTO ART. 27', '181647'),
    (686, 'SUB-0686', 'SBM2', 'LA OFICINA GENERAL DE INTEGRIDAD INSTITUCIONAL EFECTUARÁ LA PRUEBA DE INTEGRIDAD AL PERSONAL QUE FORMA PARTE DEL:.', 'SISTEMA DISCIPLINARIO POLICIAL, Y AL PERSONAL POLICIAL O CIVIL DE OTRAS ÁREAS DEL SECTOR INTERIOR', 'ART. 14', '181648'),
    (687, 'SUB-0687', 'SBM2', 'LA PRUEBA SE REALIZARA POR UNO O VARIOS DE UN COMISIONADO DE INTEGRIDAD, ES UNA CARACTERISTICA DE:.', 'LA PRUEBA DE INTEGRIDAD', 'ART. 16', '181649'),
    (688, 'SUB-0688', 'SBM2', 'SEGÚN EL ARTÍCULO 17 DEL DECRETO LEGISLATIVO 1291, LA ESPECIALIDAD DE CONTROL ADMINISTRATIVO DISCIPLINARIO, SE IMPLEMENTA DENTRO DE LA CARRERA DE LA POLICÍA NACIONAL DEL PERÚ COMO:.', 'SEGUNDA ESPECIALIDAD.', 'ART. 17', '181650'),
    (689, 'SUB-0689', 'SBM2', 'LA PRUEBA DE INTEGRIDAD PERMITE VERIFICAR SU DISPOSICIÓN DEL PERSONAL POLICIAL AL CUMPLIMIENTO DE ESTÁNDARES MÍNIMOS DE:.', 'ÉTICA, INTEGRIDAD Y HONESTIDAD.', 'ART. 11', '181651'),
    (690, 'SUB-0690', 'SBM2', 'SEGÚN EL DECRETO LEGISLATIVO 1291 ES RESPONSABILIDAD DEL JEFE DE REGION POLICIAL SUPERVISAR:.', 'EL CUMPLIMIENTO DE LAS RENDICIONES DE CUENTAS.', 'ART. 10', '181652'),
    (691, 'SUB-0691', 'SBM2', 'SEGÚN EL DECRETO LEGISLATIVO 1291, ES UNA CARACTERÍSTICA DE LA PRUEBA DE INTEGRIDAD:.', 'SI COMO RESULTADO DE LA PRUEBA SE PRESENTA UNA CONDUCTA TIPIFICADA COMO INFRACCIÓN DISCIPLINARIA O ILÍCITO PENAL, SE PROCEDERÁ DE ACUERDO A LO ESTABLECIDO EN LA NORMATIVIDAD VIGENTE.', 'ART. 16', '181653'),
    (692, 'SUB-0692', 'SBM2', 'ES AQUELLA QUE PERMITE VERIFICAR EL NIVEL DE CONFIANZA, DISCIPLINA, ÉTICA, INTEGRIDAD, TENDENCIA A COMPORTAMIENTOS NEGATIVOS Y JUICIO DEL PERSONAL EVALUADO, CON RELACIÓN AL RESPETO Y CUMPLIMIENTO DE LAS NORMAS Y CONDICIONES QUE RIGEN SU FUNCIÓN:.', 'LA EVALUACIÓN DE CONFIABILIDAD.', 'REGLAMENTO ART. 15', '181654'),
    (693, 'SUB-0693', 'SBM2', 'DE LAS ALTERNATIVAS SIGUIENTES: SEÑALE CUÁL CORRESPONDE UNA CARACTERÍSTICA DE LA PRUEBA DE INTEGRIDAD SEGÚN EL DECRETO LEGISLATIVO 1291:.', 'LA PRUEBA SE REALIZARÁ POR UNO O VARIOS DE UN COMISIONADO DE INTEGRIDAD.', 'ART. 16', '181655'),
    (694, 'SUB-0694', 'SBM2', 'DE ACUERDO A LOS LINEAMIENTOS EMITIDOS POR LA OFICINA GENERAL DE INTEGRIDAD INSTITUCIONAL, LA OFICINA GENERAL DE TECNOLOGÍAS DE LA INFORMACIÓN Y COMUNICACIONES DEL MINISTERIO DEL INTERIOR ASIGNA:.', 'LOS PERFILES DE ACCESO Y USUARIOS AL SISTEMA.', 'REGLAMENTO ART. 12', '181656'),
    (695, 'SUB-0695', 'SBM2', 'EL SOMETIMIENTO A LA PRUEBA DE CONTROL Y CONFIANZA ES VOLUNTARIO Y DEBERA CONTAR CON AUTORIZACION EXPRESA DEL:. Decreto Legislativo 1291', 'PERSONAL SELECCIONADO', 'ART. 7', '181657'),
    (696, 'SUB-0696', 'SBM2', 'LAS VACANTES EXCLUSIVAS EN LOS PROCESOS DE ASCENSO PARA CUBRIR LAS NECESIDADES DE LA ESPECIALIDAD SEGÚN EL ARTÍCULO 19 DEL DECRETO LEGISLATIVO 1291, SE REFIERE A UN:.', 'INCENTIVO DE LA ESPECIALIDAD DE CONTROL ADMINISTRATIVO DISCIPLINARIO', 'ART. 19', '181658'),
    (697, 'SUB-0697', 'SBM2', 'LA PRUEBA DE INTEGRIDAD BUSCA DETERMINAR SI EL PERSONAL POLICIAL EN ACTIVIDAD O SERVIDOR CIVIL DEL SECTOR INTERIOR TIENE UNA CONDUCTA:', 'ÍNTEGRA, PROBA, HONRADA, INCORRUPTIBLE E INSOBORNABLE', 'ART. 12', '181659'),
    (698, 'SUB-0698', 'SBM2', 'INFORMA MENSUALMENTE A LA OFICINA GENERAL DE INTEGRIDAD INSTITUCIONAL SOBRE EL CUMPLIMIENTO DE LA PRESENTACIÓN DE LAS DECLARACIONES JURADAS DE INGRESOS, BIENES Y RENTAS DEL PERSONAL POLICIAL:.', 'LA INSPECTORÍA GENERAL DE LA POLICÍA NACIONAL DEL PERÚ.', 'REGLAMENTO ART. 11', '181660'),
    (699, 'SUB-0699', 'SBM2', 'SEGÚN EL ARTÍCULO 17 DEL DECRETO LEGISLATIVO 1291, INDIQUE USTED, LA ESPECIALIDAD QUE SE IMPLEMENTA DENTRO DE LA CARRERA DE LA POLICÍA NACIONAL DEL PERÚ:.', 'ESPECIALIDAD DE CONTROL ADMINISTRATIVO DISCIPLINARIO.', 'ART. 17', '181661'),
    (700, 'SUB-0700', 'SBM2', 'LA APLICACIÓN DE LA PRUEBA DE CONTROL Y CONFIANZA SE REALIZA CON LA UTILIZACIÓN DE:.', 'SOPORTES TECNOLÓGICOS.', 'REGLAMENTO ART. 13', '181662')
)
INSERT INTO pregunta (
  banco_id, materia_id, codigo_pregunta, numero_oficial, enunciado, contexto, ubicacion_fuente, codigo_fuente, tipo_pregunta, dificultad_estimada, frecuencia_examen, tema_especifico, subtema, score_importancia, activo, revisada, creado_at, actualizado_at
)
SELECT
  b.id, m.id, d.codigo_pregunta, d.numero_oficial, d.enunciado,
  ('RESPUESTA: ' || d.respuesta_texto || ' | UBICACION: ' || COALESCE(d.ubicacion,'') || ' | CODIGO_FUENTE: ' || COALESCE(d.codigo_fuente,'')) AS contexto,
  NULLIF(d.ubicacion,''), NULLIF(d.codigo_fuente,''),
  'multiple_choice', 'medio', 'media', 'Banco Suboficiales PDF',
  COALESCE(NULLIF(d.ubicacion,''), 'Sin ubicacion'),
  70, TRUE, TRUE, NOW(), NOW()
FROM data d
JOIN banco b ON TRUE
JOIN materias m ON m.codigo = d.materia_codigo
WHERE NOT EXISTS (SELECT 1 FROM pregunta p WHERE p.codigo_pregunta = d.codigo_pregunta);

