INSERT INTO alternativa (pregunta_id, letra, texto, es_correcta, orden)
SELECT p.id, d.letra::char(1), d.texto, d.es_correcta, d.orden
FROM data d
JOIN pregunta p ON p.codigo_pregunta = d.codigo_pregunta
ON CONFLICT (pregunta_id, letra) DO UPDATE SET
  texto = EXCLUDED.texto,
  es_correcta = EXCLUDED.es_correcta,
  orden = EXCLUDED.orden;

-- Preguntas 701 a 800
WITH banco AS (
  SELECT id FROM banco_de_pregunta WHERE nombre = 'Banco Suboficiales 2025 Promo 2026 (PDF)' AND version = 'v1.0-pdf' LIMIT 1
), materias AS (
  SELECT id, codigo FROM materia WHERE codigo IN ('SBM1','SBM2','SBM3','SBM4','SBM5')
), data(numero_oficial, codigo_pregunta, materia_codigo, enunciado, respuesta_texto, ubicacion, codigo_fuente) AS (
  VALUES
    (701, 'SUB-0701', 'SBM2', 'LA INSPECTORÍA GENERAL DE LA POLICÍA NACIONAL DEL PERÚ INFORMA EL RESULTADO DE LAS PRUEBAS A SU CARGO A LA OFICINA GENERAL DE INTEGRIDAD INSTITUCIONAL DEL MINISTERIO DEL INTERIOR, DENTRO DE LOS 15 DÍAS CALENDARIO POSTERIORES A SU EJECUCIÓN A TRAVES DE: MARQUE LA QUE CORRESPONDE:.', 'LA DELEGACIÓN DE LA APLICACIÓN DE LAS PRUEBAS', 'DISPOSICIÓN COMPLEMENTARIA FINAL', '181663'),
    (702, 'SUB-0702', 'SBM2', 'SEGÚN AL ARTÍCULO 18 DEL DECRETO LEGISLATIVO 1291, EL PERSONAL POLICIAL ACCEDE A LA ESPECIALIDAD DE CONTROL ADMINISTRATIVO DISCIPLINARIO Y PERMANECERÁ EN ÉSTA:.', 'HASTA EL TÉRMINO DE SU CARRERA.', 'ART. 18', '181664'),
    (703, 'SUB-0703', 'SBM2', 'TIENE COMO OBJETIVO FORTALECER LOS NIVELES DE CONFIABILIDAD Y SEGURIDAD, MEDIANTE LA IDENTIFICACIÓN DE PERSONAL CUYAS CONDUCTAS, PRINCIPIOS Y VALORES SEAN ACORDES A LOS INSTITUCIONALES: MARQUE LA RESPUESTA CORRECTA:.', 'LA PRUEBA DE CONTROL Y CONFIANZA.', 'REGLAMENTO ART. 13', '181665'),
    (704, 'SUB-0704', 'SBM2', 'LA OFICINA GENERAL DE INTEGRIDAD INSTITUCIONAL, SELECCIONA LOS COMISIONADOS DE INTEGRIDAD POR INTERMEDIO DE:.', 'LA OFICINA DE CONTROL, CUMPLIMIENTO Y CONFIANZA.', 'REGLAMENTO ART. 31', '181666'),
    (705, 'SUB-0705', 'SBM2', 'CUANDO EN EL DECRETO SUPREMO 013-2017-IN, SE MENCIONE SIN ESPECIFICAR LAS PALABRAS; SECTOR, MINISTERIO, POLICÍA NACIONAL DEL PERÚ Y SISTEMA, NOS ESTAMOS REFIRIENDO A:.', 'NOMENCLATURA.', 'REGLAMENTO ART. 2', '181667'),
    (706, 'SUB-0706', 'SBM2', 'SEGÚN LAS RESTRICCIONES Y RESERVAS SEÑALADAS EN LA PRESENTE NORMA, EL PERSONAL DE LOS DIFERENTES ÓRGANOS Y UNIDADES ORGÁNICAS DEL SECTOR INTERIOR, INCLUYENDO A LA POLICÍA NACIONAL DEL PERÚ, ESTA OBLIGADO A MANTENER:.', 'ESTRICTA RESERVA Y CONFIDENCIALIDAD DE TODA LA INFORMACION OBTENIDA.', 'REGLAMENTO ART. 3', '181668'),
    (707, 'SUB-0707', 'SBM2', 'SEÑALE EL ENUNCIADO QUE CORRESPONDA A UN INCENTIVO DE LA ESPECIALIDAD DE CONTROL ADMINISTRATIVO DISCIPLINARIO:.', 'EL PERSONAL SELECCIONADO NO PODRÁ PASAR AL RETIRO POR CAUSAL DE RENOVACIÓN DE CUADROS.', 'ART. 19', '181670'),
    (708, 'SUB-0708', 'SBM2', '¿QUE OFICINA VERIFICARÁ LA INFORMACIÓN CONTENIDA EN LAS DECLARACIONES JURADAS DE BIENES Y RENTAS DEL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ?:.', 'LA OFICINA GENERAL DE INTEGRIDAD INSTITUCIONAL', 'ART. 6', '181671'),
    (709, 'SUB-0709', 'SBM2', 'LA PRUEBA DE INTEGRIDAD BUSCA DETERMINAR SI EL PERSONAL POLICIAL EN ACTIVIDAD O SERVIDOR CIVIL DEL SECTOR INTERIOR TIENE UNA CONDUCTA:.', 'INTEGRA.', 'ART. 12', '181672'),
    (710, 'SUB-0710', 'SBM2', 'LA RENDICIÓN DE CUENTAS ESTARÁ REFERIDA AL INCREMENTO O DISMINUCIÓN DE LA CRIMINALIDAD DENTRO DE LA JURISDICCIÓN, ASÍ COMO A LAS DIFICULTADES CON QUE PUEDA HABERSE ENCONTRADO________________________________________EN LA EJECUCIÓN DE SUS ACTIVIDADES: MARQUE LA RESPUESTA:.', '. A) PARA EL CUMPLIMIENTO DE SU MISIÓN. B) LA POLICÍA NACIONAL DEL PERÚ. C) LA INSPECTORÍA GENERAL DE LA POLICÍA NACIONAL DEL PERÚ D) EL COMISARIO DE LA JURISDICCIÓN. E) EL JEFE DE LA REGIÓN POLICIAL RESPUESTA: LA POLICÍA NACIONAL DEL PERÚ.', 'REGLAMENTO ART. 24', '181673'),
    (711, 'SUB-0711', 'SBM2', 'A QUIEN LE CORRESPONDE ELABORAR LAS DIRECTIVAS QUE ESTABLEZCAN LOS PROTOCOLOS, PROCEDIMIENTOS, METAS, OBJETIVOS Y PLAZOS PARA LA APLICACIÓN DE LAS PRUEBAS: MARQUE LA RESPUESTA CORRECTA:', 'A LA OFICINA DE CONTROL, CUMPLIMIENTO Y CONFIANZA.', 'REGLAMENTO ART. 20', '181674'),
    (712, 'SUB-0712', 'SBM2', '¿INDIQUE USTED UNA CARACTERÍSTICA DE LA PRUEBA DE INTEGRIDAD, SEGÚN EL DECRETO LEGISLATIVO 1291?. Decreto Legislativo 1291', 'EL COMISIONADO DE INTEGRIDAD ACTUARÁ SIN PROVOCAR SITUACIONES COMPROMETEDORAS QUE INDUZCAN A LA COMISIÓN DE ACTOS CONTRARIOS A LA LEY.', 'ART. 16', '181675'),
    (713, 'SUB-0713', 'SBM2', 'LA PRUEBA DE INTEGRIDAD ES LA EVALUACIÓN REALIZADA AL PERSONAL CIVIL:', 'DEL SECTOR INTERIOR.', 'ART. 11', '181676'),
    (714, 'SUB-0714', 'SBM2', 'CONTENIDO DE LA PRUEBA.- NO PODRÁN CONSTITUIR ACTOS MANIFIESTAMENTE PROVOCADORES QUE SIGNIFIQUEN HECHOS INDUCTIVOS O INSTIGADORES PARA LA COMISIÓN DE UNA CONDUCTA FUNCIONAL IRREGULAR. CORRESPONDE A:', 'LAS ACCIONES SIMULADAS.', 'REGLAMENTO ART. 30', '181677'),
    (715, 'SUB-0715', 'SBM2', 'ES AQUELLA MEDIANTE LA CUAL SE VERIFICA LA REACCIÓN PSICOFISIOLÓGICA DEL EVALUADO ANTE LA APLICACIÓN DE UN CUESTIONARIO A FIN DE ESTABLECER LA VERACIDAD DE LA INFORMACIÓN PROPORCIONADA, NOS REFERIMOS A:', 'LA EVALUACIÓN MEDIANTE LA UTILIZACIÓN DE POLÍGRAFO O INSTRUMENTOS SIMILARES', 'REGLAMENTO ART. 17', '181680'),
    (716, 'SUB-0716', 'SBM2', 'DENTRO DE LAS RESTRICCIONES Y RESERVAS. LA OFICINA DE CONTROL, CUMPLIMIENTO Y CONFIANZA, ASÍ COMO EL PERSONAL POLICIAL, PERICIAL O TÉCNICO QUE PARTICIPE EN LA PRUEBA, SE ENCUENTRA OBLIGADO A MANTENER ESTRICTA CONFIDENCIALIDAD RESPECTO DE: MARQUE LA RESPUESTA CORRECTA:', 'LA INFORMACIÓN OBTENIDA CON LAS PRUEBAS DE CONTROL Y CONFIANZA.', 'REGLAMENTO ART. 22', '181681'),
    (717, 'SUB-0717', 'SBM2', 'EN EL CASO DE LA PRUEBA DEL POLÍGRAFO, SE INCORPORAN ADICIONALMENTE LAS AUTORIZACIONES DE SOMETIMIENTO A DICHAS PRUEBAS O:', 'SU NEGATIVA DE SER EL CASO.', 'REGLAMENTO ART. 4', '181682'),
    (718, 'SUB-0718', 'SBM2', 'ES OBJETIVO QUE LOS ÓRGANOS Y UNIDADES ORGÁNICAS DEL SISTEMA DISCIPLINARIO POLICIAL CUENTEN CON PERSONAL POLICIAL ALTAMENTE CALIFICADO Y CON EL PERFIL IDÓNEO QUE PERMITA REALIZAR UNA LABOR PROFESIONAL Y EFECTIVA PARA:.', 'EL CONTROL DEL BUEN USO DE LOS RECURSOS ASIGNADOS POR EL ESTADO, ASÍ COMO LA PRESERVACIÓN DE LOS BIENES JURÍDICOS QUE SUSTENTAN LA FUNCIÓN POLICIAL', 'ART. 18', '181683'),
    (719, 'SUB-0719', 'SBM2', 'DENTRO DE LAS FUNCIONES DE LA OFICINA DE CONTROL, CUMPLIMIENTO Y CONFIANZA, ES DICTAR LOS LINEAMIENTOS PARA GARANTIZAR: MARQUE LA QUE CORRESPONDA', 'LA CONFIDENCIALIDAD Y RESERVA DE LA INFORMACIÓN A LAS DECLARACIONES JURADAS DE INGRESOS, BIENES Y RENTAS REGISTRADAS EN EL SISTEMA.', 'REGLAMENTO ART. 10', '181685'),
    (720, 'SUB-0720', 'SBM2', 'DE CONFORMIDAD AL DECRETO LEGISLATIVO 1291 ES RESPONSABILIDAD DE LOS JEFES DE LOS FRENTES POLICIALES:', 'SUPERVISAR EL CUMPLIMIENTO DE LAS RENDICIONES DE CUENTAS.', 'ART. 10', '181687'),
    (721, 'SUB-0721', 'SBM2', 'SEÑALE EL ENUNCIADO QUE CORRESPONDA A UN INCENTIVO DE LA ESPECIALIDAD DE CONTROL ADMINISTRATIVO DISCIPLINARIO:.', 'CAPACITACIÓN PERMANENTE EN EL PAÍS Y EN EXTRANJERO POR CADA GRADO', 'ART. 19', '181688'),
    (722, 'SUB-0722', 'SBM2', 'EL CONTENIDO DE LA DECLARACIÓN JURADA DE INGRESOS, BIENES Y RENTAS:', 'NO OBLIGA A LA PRESENTACIÓN DE DOCUMENTOS QUE SUSTENTEN SU CONTENIDO', 'REGLAMENTO ART. 9', '181690'),
    (723, 'SUB-0723', 'SBM2', 'LA PRUEBA DE CONTROL Y CONFIANZA SE APLICA AL PERSONAL CIVIL Y POLICIAL DEL SECTOR INTERIOR Y TIENE COMO OBJETIVO FORTALECER LOS NIVELES DE CONFIABILIDAD Y SEGURIDAD, MEDIANTE LA IDENTIFICACIÓN DE PERSONAL: MARQUE LA RESPUESTA CORRECTA:.', 'CUYAS CONDUCTAS, PRINCIPIOS Y VALORES SEAN ACORDES A LOS INSTITUCIONALES', 'REGLAMENTO ART. 13', '181698'),
    (724, 'SUB-0724', 'SBM2', 'LA PRUEBA DE CONTROL Y CONFIANZA NO PUEDE SER APLICADA DENTRO DE UN PROCEDIMIENTO: MARQUE LA RESPUESTA:.', '. A) ADMINISTRATIVO DISCIPLINARIO LABORAL. B) ADMINISTRATIVO DISCIPLINARIO SANCIONADOR. C) ADMINISTRATIVO DISCIPLINARIO CIVIL. D) CONTENCIOSO O ADMINISTRATIVO. E) ADMINISTRATIVO LABORAL. RESPUESTA: ADMINISTRATIVO DISCIPLINARIO SANCIONADOR.', 'REGLAMENTO ART. 22', '181699'),
    (725, 'SUB-0725', 'SBM2', '¿MEDIANTE QUE MEDIDA RENDIRÁN CUENTA LAS AUTORIDADES POLICIALES ANTE SU COMUNIDAD?:', 'AUDIENCIAS PÚBLICAS CON LA PARTICIPACIÓN DE AUTORIDADES Y SOCIEDAD CIVIL', 'ART. 10', '181700'),
    (726, 'SUB-0726', 'SBM2', 'ES UNA CARACTERÍSTICA DE LA PRUEBA DE CONTROL Y CONFIANZA:', 'EL RESULTADO DE LA PRUEBA TIENE CARÁCTER DE INFORMACIÓN CONFIDENCIAL', 'ART. 9', '181703'),
    (727, 'SUB-0727', 'SBM2', 'LAS AUTORIDADES POLICIALES DENTRO DE SU JURISDICCIÓN, RESPECTO A LA GESTIÓN REALIZADA ESTÁN OBLIGADOS A RENDIR CUENTA ANTE:', 'SU COMUNIDAD.', 'ART. 10', '181704'),
    (728, 'SUB-0728', 'SBM2', 'SEGÚN EL DECRETO LEGISLATIVO 1291 LA RENDICION DE CUENTAS SE REALIZA:', 'TRIMESTRALMENTE.', 'ART. 10', '181705'),
    (729, 'SUB-0729', 'SBM2', 'SEGÚN EL DECRETO LEGISLATIVO 1291, SON RESPONSABLES DE SUPERVISAR EL CUMPLIMIENTO DE LAS RENDICIONES DE CUENTAS:', 'EL JEFE DE REGION POLICIAL, FRENTES POLICIALES O DIRECCIONES ESPECIALIZADAS.', 'ART. 10', '181706'),
    (730, 'SUB-0730', 'SBM2', 'ES LA EVALUACIÓN REALIZADA AL PERSONAL POLICIAL EN SITUACIÓN DE ACTIVIDAD Y AL PERSONAL CIVIL DEL SECTOR INTERIOR:', 'LA PRUEBA DE INTEGRIDAD.', 'ART. 11', '181707'),
    (731, 'SUB-0731', 'SBM2', 'ES EL RESPONSABLE DE EJERCER AUTORIDAD EN TODO LUGAR Y CIRCUNSTANCIA, ASÍ COMO MANTENER LA DISCIPLINA MEDIANTE LA INSTRUCCIÓN, EL MANDO JUSTO, EL BUEN EJEMPLO Y LA IMPARCIALIDAD:', 'EL SUPERIOR', 'ART. 8', '177928'),
    (732, 'SUB-0732', 'SBM2', 'EL SUPERIOR ES EL RESPONSABLE DE EJERCER AUTORIDAD EN TODO LUGAR Y CIRCUNSTANCIA, ASÍ COMO MANTENER LA DISCIPLINA MEDIANTE:', 'LA INSTRUCCIÓN, EL MANDO JUSTO, EL BUEN EJEMPLO Y LA IMPARCIALIDAD.', 'ART. 8', '177929'),
    (733, 'SUB-0733', 'SBM2', 'OBEDECERÁ LAS ÓRDENES RECIBIDAS SIEMPRE QUE NO SEAN CONTRARIAS A LO SEÑALADO EN LA CONSTITUCIÓN POLÍTICA DEL PERÚ Y LA NORMATIVIDAD VIGENTE Y DARÁ CUENTA DE SU CUMPLIMIENTO AL SUPERIOR QUE LAS IMPARTIÓ:', 'EL SUBORDINADO', 'ART. 9', '177930'),
    (734, 'SUB-0734', 'SBM2', '¿QUÉ SUCEDE CUANDO ALGÚN MIEMBRO DE LA POLICÍA NACIONAL DEL PERÚ, EN SITUACIÓN DE RETIRO, SE CONSIDERE AFECTADO POR UNA CONDUCTA QUE CONSTITUYA INFRACCIÓN COMETIDA POR OTRO MIEMBRO DE LA INSTITUCIÓN EN SITUACIÓN DE ACTIVIDAD?', 'PODRÁ SOLICITAR LA INVESTIGACIÓN O SANCIÓN CORRESPONDIENTE.', 'ART. 10', '177931'),
    (735, 'SUB-0735', 'SBM2', 'SURTE EFECTO INMEDIATO POR SU PROPIA NATURALEZA, NO SIENDO NECESARIA LA EMISIÓN DE RESOLUCIÓN ADICIONAL ALGUNA:', 'LA RESOLUCIÓN DE SANCIÓN POR INFRACCIÓN GRAVE Y MUY GRAVE FIRME DEBIDAMENTE NOTIFICADA.', 'ART. 32', '177932'),
    (736, 'SUB-0736', 'SBM2', 'SE NOTIFICA DE INMEDIATO AL INFRACTOR Y SE REMITIRÁ A LA DIRECCIÓN EJECUTIVA DE PERSONAL DENTRO DEL PLAZO DE 3 DÍAS HÁBILES, PARA SU CODIFICACIÓN, SISTEMATIZACIÓN Y ARCHIVO EN EL LEGAJO PERSONAL:', 'LA SANCIÓN POR INFRACCIÓN LEVE.', 'ART. 32', '177933'),
    (737, 'SUB-0737', 'SBM2', '¿QUÉ SUCEDE CUANDO ALGÚN MIEMBRO DE LA POLICÍA NACIONAL DEL PERÚ, EN SITUACIÓN DE DISPONIBILIDAD, SE CONSIDERE AFECTADO POR UNA CONDUCTA QUE CONSTITUYA INFRACCIÓN COMETIDA POR OTRO MIEMBRO DE LA INSTITUCIÓN EN SITUACIÓN DE DISPONIBILIDAD?', 'PODRÁ SOLICITAR LA INVESTIGACIÓN O SANCIÓN CORRESPONDIENTE.', 'ART. 10', '177934'),
    (738, 'SUB-0738', 'SBM2', '¿CUÁNDO EL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ PODRÁ INFORMAR O DAR ENTREVISTAS A TRAVÉS DE LOS MEDIOS DE COMUNICACIÓN SOCIAL?', 'CUANDO TENGA AUTORIZACIÓN EXPRESA DE SU COMANDO.', 'ART.11', '177935'),
    (739, 'SUB-0739', 'SBM2', '¿CUÁNDO EL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ PODRÁ INFORMAR O DAR ENTREVISTAS A TRAVÉS DE LOS MEDIOS DE COMUNICACIÓN SOCIAL?', 'CUANDO TENGA AUTORIZACIÓN EXPRESA DE LOS ÓRGANOS ENCARGADOS DEL SISTEMA DE INFORMACIÓN Y COMUNICACIÓN SOCIAL DE LA INSTITUCIÓN.', 'ART. 11', '177936'),
    (740, 'SUB-0740', 'SBM2', 'SEÑALE UNO DE LOS CRITERIOS A CONSIDERAR PARA DETERMINAR LA SANCIÓN A IMPONER:', 'LAS CIRCUNSTANCIAS EN QUE SE COMETIÓ LA INFRACCIÓN.', 'ART. 31', '177937'),
    (741, 'SUB-0741', 'SBM2', 'SEÑALE UNO DE LOS CRITERIOS A CONSIDERAR PARA DETERMINAR LA SANCIÓN A IMPONER:', 'LA MAGNITUD DE LOS DAÑOS Y PERJUICIOS OCASIONADOS.', 'ART. 31', '177938'),
    (742, 'SUB-0742', 'SBM2', 'SEÑALE UNO DE LOS CRITERIOS A CONSIDERAR PARA DETERMINAR LA SANCIÓN A IMPONER:', 'LA REPARACIÓN O RESARCIMIENTO OPORTUNO DEL DAÑO ANTES DE LA SANCIÓN.', 'ART. 31', '177939'),
    (743, 'SUB-0743', 'SBM2', 'SEÑALE UNO DE LOS CRITERIOS A CONSIDERAR PARA DETERMINAR LA SANCIÓN A IMPONER:', 'LOS ANTECEDENTES ADMINISTRATIVO-DISCIPLINARIOS REGISTRADOS EN EL REPORTE DE INFORMACIÓN PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ.', 'ART. 31', '177940'),
    (744, 'SUB-0744', 'SBM2', 'SEÑALE UNO DE LOS CRITERIOS A CONSIDERAR PARA DETERMINAR LA SANCIÓN A IMPONER:', 'EL GRADO DE COLABORACIÓN PARA EL ESCLARECIMIENTO DE LOS HECHOS.', 'ART. 31', '177941'),
    (745, 'SUB-0745', 'SBM2', 'SEÑALE UNO DE LOS CRITERIOS A CONSIDERAR PARA DETERMINAR LA SANCIÓN A IMPONER:', 'USO DEL CARGO PARA COMETER LA INFRACCIÓN.', 'ART. 31', '177942'),
    (746, 'SUB-0746', 'SBM2', 'SEÑALE UNO DE LOS CRITERIOS A CONSIDERAR PARA DETERMINAR LA SANCIÓN A IMPONER:', 'LA CONFESIÓN ESPONTÁNEA Y SINCERA.', 'ART. 31', '177943'),
    (747, 'SUB-0747', 'SBM2', 'SEÑALE UNO DE LOS CRITERIOS A CONSIDERAR PARA DETERMINAR LA SANCIÓN A IMPONER:', 'MAYOR RESPONSABILIDAD DEL EFECTIVO MÁS ANTIGUO EN LA COMISIÓN DE LA INFRACCIÓN.', 'ART. 31', '177944'),
    (748, 'SUB-0748', 'SBM2', 'PROCEDIMIENTO ADMINISTRATIVO-DISCIPLINARIO POR INFRACCIÓN LEVE.- HABIENDO CONSTATADO O TOMADO CONOCIMIENTO DE LA COMISIÓN DE INFRACCIÓN LEVE DEL INVESTIGADO, SE NOTIFICA POR ESCRITO LA IMPUTACIÓN DE LA INFRACCIÓN PARA QUE FORMULE EL DESCARGO POR ESCRITO AL SUPERIOR QUE SANCIONA. ¿EN QUÉ PLAZO EL INVESTIGADO DEBE PRESENTAR SUS DESCARGOS?', '1 DÍA HÁBIL.', 'ART. 62', '177945'),
    (749, 'SUB-0749', 'SBM2', 'PROCEDIMIENTO ADMINISTRATIVO-DISCIPLINARIO POR INFRACCIÓN LEVE.- ¿QUÉ PLAZO TIENE EL SANCIONADO PARA APELAR LA SANCIÓN IMPUESTA POR EL SUPERIOR?', '3 DÍAS HÁBILES.', 'ART. 62', '177946'),
    (750, 'SUB-0750', 'SBM2', 'PROCEDIMIENTO ADMINISTRATIVO-DISCIPLINARIO POR INFRACCIÓN LEVE.- EN SEGUNDA INSTANCIA RESUELVE EL JEFE DE UNIDAD O SUB UNIDAD POLICIAL DONDE PRESTA SERVICIOS EL SUPERIOR QUE SANCIONA, EN EL PLAZO DE:', '5 DÍAS HÁBILES.', 'ART. 62', '177947'),
    (751, 'SUB-0751', 'SBM2', 'LA RESOLUCIÓN ABSOLUTORIA EN EL PROCEDIMIENTO ADMINISTRATIVO-DISCIPLINARIO, IMPLICA QUE EL INVESTIGADO QUE SE ENCUENTRE CON MEDIDA DE SUSPENSIÓN TEMPORAL DEL SERVICIO SERÁ REINCORPORADO AUTOMÁTICAMENTE AL SERVICIO ACTIVO, NO CONSIDERÁNDOSE COMO INTERRUPCIÓN DEL TIEMPO DE SERVICIOS, EL PERÍODO QUE DURÓ DICHA MEDIDA Y REINTEGRÁNDOSELE SOLO ...:', 'EL 50% NO PERCIBIDO DE LA REMUNERACIÓN CONSOLIDADA POR EL PERÍODO QUE DURÓ LA MEDIDA', 'ART. 82', '177948'),
    (752, 'SUB-0752', 'SBM2', 'EL PROCEDIMIENTO ADMINISTRATIVO-DISCIPLINARIO PARA INFRACCIONES GRAVES O MUY GRAVES SE INICIA CON LA NOTIFICACIÓN DE LA RESOLUCIÓN DE INICIO DEL PROCEDIMIENTO ADMINISTRATIVO-DISCIPLINARIO, EMITIDA POR EL ÓRGANO DE INVESTIGACIÓN CORRESPONDIENTE, PARA QUE EL INVESTIGADO TOME CONOCIMIENTO Y EJERZA SU DERECHO A LA DEFENSA; DEBIENDO FORMULAR SUS DESCARGOS EN UN PLAZO NO MAYOR DE ...:', '10 DÍAS HÁBILES DE RECIBIDA VÁLIDAMENTE LA NOTIFICACIÓN.', 'ART. 63', '177949'),
    (753, 'SUB-0753', 'SBM2', 'PROCEDE RECURSO DE APELACIÓN CONTRA:', 'LAS RESOLUCIONES DE SANCIÓN.', 'ART. 53', '177950'),
    (754, 'SUB-0754', 'SBM2', 'CONSTITUYE UNA CIRCUNSTANCIA ATENUANTE:', 'LA CONFESIÓN SINCERA Y ESPONTÁNEA DE HABER COMETIDO LA INFRACCIÓN O COLABORACIÓN EN LA INVESTIGACIÓN PARA EL MEJOR ESCLARECIMIENTO DE LOS HECHOS.', 'ART. 55', '177951'),
    (755, 'SUB-0755', 'SBM2', 'COMETER LA INFRACCIÓN EN PRESENCIA DE SUBORDINADOS.', 'CONSTITUYE UNA CIRCUNSTANCIA AGRAVANTE.', 'ART. 56', '177952'),
    (756, 'SUB-0756', 'SBM2', 'CONSTITUYE UNA CIRCUNSTANCIA ATENUANTE:', 'TENER MENOS DE 3 MESES COMO EGRESADO DE LAS ESCUELAS DE FORMACIÓN O ENCONTRARSE EN PERÍODO DE ASIMILACIÓN.', 'ART. 55', '177953'),
    (757, 'SUB-0757', 'SBM2', 'LA REINCIDENCIA EN LA COMISIÓN DE INFRACCIONES ADMINISTRATIVAS.', 'CONSTITUYE UNA CIRCUNSTANCIA AGRAVANTE.', 'ART. 56', '177954'),
    (758, 'SUB-0758', 'SBM2', 'LA CONFESIÓN SINCERA Y ESPONTÁNEA DE HABER COMETIDO LA INFRACCIÓN O COLABORACIÓN EN LA INVESTIGACIÓN PARA EL MEJOR ESCLARECIMIENTO DE LOS HECHOS.', 'CONSTITUYE UNA CIRCUNSTANCIA ATENUANTE.', 'ART. 55', '177955'),
    (759, 'SUB-0759', 'SBM2', 'TENER MENOS DE 3 MESES COMO EGRESADO DE LAS ESCUELAS DE FORMACIÓN O ENCONTRARSE EN PERÍODO DE ASIMILACIÓN.', 'CONSTITUYE UNA CIRCUNSTANCIA ATENUANTE.', 'ART. 55', '177956'),
    (760, 'SUB-0760', 'SBM2', 'OBRAR COMO COLABORADOR EN LA INVESTIGACIÓN PARA EL ESCLARECIMIENTO DE LOS HECHOS.', 'CONSTITUYE UNA CIRCUNSTANCIA EXIMENTE.', 'ART. 54', '177957'),
    (761, 'SUB-0761', 'SBM2', 'OBRAR POR UNA FUERZA FÍSICA IRRESISTIBLE PROVENIENTE DE UN TERCERO O DE LA NATURALEZA.', 'CONSTITUYE UNA CIRCUNSTANCIA EXIMENTE.', 'ART. 54', '177958'),
    (762, 'SUB-0762', 'SBM2', 'CAUSAR UN DAÑO POR EVITAR OTRO MAYOR, SIEMPRE QUE ESTE ÚLTIMO SEA EFECTIVO Y NO SE PUEDA RAZONABLEMENTE EXIGIR AL AUTOR EL SACRIFICIO DEL BIEN AMENAZADO Y QUE, DADAS LAS CIRCUNSTANCIAS, NO HAYA PODIDO EMPLEAR OTRO MEDIO MENOS PERJUDICIAL.', 'CONSTITUYE UNA CIRCUNSTANCIA EXIMENTE.', 'ART. 54', '177959'),
    (763, 'SUB-0763', 'SBM2', 'PROCEDER EN VIRTUD DE OBEDIENCIA AL SUPERIOR, SIEMPRE QUE LA ORDEN DE ESTE NO SEA MANIFIESTAMENTE ILÍCITA.', 'CONSTITUYE UNA CIRCUNSTANCIA EXIMENTE.', 'ART. 54', '177960'),
    (764, 'SUB-0764', 'SBM2', 'OBRAR BAJO EL ESTADO DE ENFERMEDAD PSICÓTICA ACREDITADA, QUE HAYA IMPEDIDO TOTALMENTE AL ACTOR APRECIAR EL CARÁCTER ILÍCITO DEL ACTO Y SUPRIMIDO SU CAPACIDAD PARA OBRAR LIBREMENTE.', 'CONSTITUYE UNA CIRCUNSTANCIA EXIMENTE.', 'ART. 54', '177961'),
    (765, 'SUB-0765', 'SBM2', 'OBRAR POR DISPOSICIÓN DE UNA NORMA LEGAL, EN CUMPLIMIENTO DE UN DEBER O EN VIRTUD DE UN MANDATO JUDICIAL O PRIVILEGIANDO UN DERECHO O UN BIEN JURÍDICO SUPERIOR, SIEMPRE QUE SE ACTÚE CON LA DILIGENCIA DEBIDA.', 'CONSTITUYE UNA CIRCUNSTANCIA EXIMENTE.', 'ART. 54', '177962'),
    (766, 'SUB-0766', 'SBM2', 'OBRAR EN SALVAGUARDA DE LA VIDA O INTEGRIDAD FÍSICA PROPIA O DE OTRAS PERSONAS, ACTUANDO CON LA DILIGENCIA DEBIDA:', 'CONSTITUYE UNA CIRCUNSTANCIA EXIMENTE.', 'ART. 54', '177963'),
    (767, 'SUB-0767', 'SBM2', 'EL PROCEDIMIENTO ADMINISTRATIVO-DISCIPLINARIO CONCLUYE:', 'POR MUERTE DEL INVESTIGADO, PRESCRIPCIÓN DE LA POTESTAD SANCIONADORA DISCIPLINARIA O RESOLUCIÓN FIRME DE SANCIÓN O ABSOLUCIÓN.', 'ART. 53', '177964'),
    (768, 'SUB-0768', 'SBM2', 'SER NOTIFICADO DE LA RESOLUCIÓN QUE PONE FIN AL PROCEDIMIENTO-ADMINISTRATIVO DISCIPLINARIO.', 'ES UN DERECHO DEL INVESTIGADO.', 'ART. 52', '177965'),
    (769, 'SUB-0769', 'SBM2', 'RESPECTO A LOS DERECHOS DEL INVESTIGADO, INDIQUE LA RESPUESTA CORRECTA:', 'ACCEDER A LA INFORMACIÓN RELACIONADA A SU CASO, EN CUALQUIER FASE DEL PROCEDIMIENTO ADMINISTRATIVODISCIPLINARIO, OBSERVANDO LAS EXCEPCIONES DE LEY.', 'ART. 52', '177966'),
    (770, 'SUB-0770', 'SBM2', 'ACCEDER A LA INFORMACIÓN RELACIONADA A SU CASO, EN CUALQUIER FASE DEL PROCEDIMIENTO ADMINISTRATIVODISCIPLINARIO, OBSERVANDO LAS EXCEPCIONES DE LEY.', 'ES UN DERECHO DEL INVESTIGADO.', 'ART. 52', '177967'),
    (771, 'SUB-0771', 'SBM2', 'OBTENER COPIAS DE LOS DOCUMENTOS, ASUMIENDO SU COSTO.', 'ES UN DERECHO DEL INVESTIGADO.', 'ART. 52', '177968'),
    (772, 'SUB-0772', 'SBM2', 'SOLICITAR, EN CASO DE CONSIDERARLO NECESARIO, INFORME ORAL ANTE EL ÓRGANO DE DECISIÓN.', 'ES UN DERECHO DEL INVESTIGADO.', 'ART. 52', '177969'),
    (773, 'SUB-0773', 'SBM2', 'CONOCER LOS HECHOS QUE SE LE IMPUTAN, LA INFRACCIÓN POR LA QUE ES INVESTIGADO Y LA SANCIÓN QUE LE CORRESPONDERÍA; CONSTITUYE:', 'UN DERECHO DEL INVESTIGADO.', 'ART. 52', '177972'),
    (774, 'SUB-0774', 'SBM2', 'LA VERIFICACIÓN DOCUMENTARIA; CONSTITUYE:', 'UNA DE LAS ACCIONES PREVIAS QUE PUEDEN REALIZARSE PARA EL INICIO DEL PROCEDIMIENTO ADMINISTRATIVO-DISCIPLINARIO.', 'ART. 50', '177973'),
    (775, 'SUB-0775', 'SBM2', 'EL PLAZO PARA LA REALIZACIÓN DE LAS ACCIONES PREVIAS NO SERÁ MAYOR DE:', '30 DÍAS HÁBILES.', 'ART. 51', '177974'),
    (776, 'SUB-0776', 'SBM2', 'SON DILIGENCIAS QUE PUEDEN DISPONER Y REALIZAR LOS ÓRGANOS DE INVESTIGACIÓN COMPETENTES, SOLO CUANDO SEA NECESARIO IDENTIFICAR AL PRESUNTO INFRACTOR O INFRACTORES O UBICAR Y ACOPIAR INDICIOS, EVIDENCIAS, ELEMENTOS DE PRUEBA Y OTROS QUE SEAN PERTINENTES PARA EL INICIO DEL PROCEDIMIENTO ADMINISTRATIVO-DISCIPLINARIO:', 'LAS ACCIONES PREVIAS.', 'ART. 50', '177976'),
    (777, 'SUB-0777', 'SBM2', 'LAS VISITAS DE CONSTATACIÓN; CONSTITUYE:', 'UNA DE LAS ACCIONES PREVIAS QUE PUEDEN REALIZARSE PARA EL INICIO DEL PROCEDIMIENTO ADMINISTRATIVO-DISCIPLINARIO.', 'ART. 50', '177977'),
    (778, 'SUB-0778', 'SBM2', 'CONSTITUYE UNA FUNCIÓN DEL TRIBUNAL DE DISCIPLINA POLICIAL:', 'CONOCE Y RESUELVE EN APELACIÓN O CONSULTA, LAS ABSOLUCIONES Y SANCIONES DE INFRACCIONES GRAVES Y LEVES, SIEMPRE QUE ESTAS HAYAN SIDO IMPUTADAS CON INFRACCIONES MUY GRAVES EN UN MISMO PROCEDIMIENTO ADMINISTRATIVO DISCIPLINARIO', 'ART. 49', '177978'),
    (779, 'SUB-0779', 'SBM2', 'CONSTITUYE UNA FUNCIÓN DEL TRIBUNAL DE DISCIPLINA POLICIAL:', 'CONOCER Y RESOLVER LOS RECURSOS DE APELACIÓN INTERPUESTOS CONTRA LAS RESOLUCIONES QUE DISPONEN MEDIDAS PREVENTIVAS POR INFRACCIONES MUY GRAVES EN CASO DE OFICIALES GENERALES.', 'ART. 49', '177979'),
    (780, 'SUB-0780', 'SBM2', 'CONSTITUYE UNA FUNCIÓN DEL TRIBUNAL DE DISCIPLINA POLICIAL:', 'CONOCER Y RESOLVER EN ÚLTIMA Y DEFINITIVA INSTANCIA LOS RECURSOS DE APELACIÓN CONTRA LAS RESOLUCIONES QUE IMPONEN SANCIONES POR INFRACCIONES MUY GRAVES, ASÍ COMO LAS SANCIONES IMPUESTAS POR EL INSPECTOR GENERAL DE LA POLICÍA NACIONAL DEL PERÚ. ASIMISMO, CONOCE Y RESUELVE LAS RESOLUCIONES EXPEDIDAS POR LOS ÓRGANOS DISCIPLINARIOS COMPETENTES, CONFORME LO ESTABLECE ESTA LEY.', 'ART. 49', '177980'),
    (781, 'SUB-0781', 'SBM2', 'CONSTITUYE UNA FUNCIÓN DE LOS ÓRGANOS DE DECISIÓN DEL SISTEMA DISCIPLINARIO:', 'PONER EN CONOCIMIENTO DE LA DIRECCIÓN EJECUTIVA DE PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ PARA SU REGISTRO Y EJECUCIÓN CORRESPONDIENTE, LA RESOLUCIÓN, DEBIDAMENTE NOTIFICADA AL INTERESADO, QUE RESUELVE EL PROCEDIMIENTO ADMINISTRATIVO-DISCIPLINARIO.', 'ART. 48', '177981'),
    (782, 'SUB-0782', 'SBM2', 'CONSTITUYE UNA FUNCIÓN DE LOS ÓRGANOS DE DECISIÓN DEL SISTEMA DISCIPLINARIO:', 'PONER EN CONOCIMIENTO DEL INTERESADO LA RESOLUCIÓN QUE RESUELVE EL PROCEDIMIENTO ADMINISTRATIVO-DISCIPLINARIO.', 'ART. 48 Ley N° 30714 - Régimen Disciplinario PNP', '177982'),
    (783, 'SUB-0783', 'SBM2', 'CONSTITUYE UNA FUNCIÓN DE LOS ÓRGANOS DE DECISIÓN DEL SISTEMA DISCIPLINARIO:', 'DISPONER A LOS ÓRGANOS DE INVESTIGACIÓN LA REALIZACIÓN DE ACCIONES DE INVESTIGACIÓN COMPLEMENTARIAS; EN CASO RESULTE NECESARIO.', 'ART. 48', '177983'),
    (784, 'SUB-0784', 'SBM2', 'CONSTITUYE UNA FUNCIÓN DE LOS ÓRGANOS DE DECISIÓN DEL SISTEMA DISCIPLINARIO:', 'RESOLVER MEDIANTE RESOLUCIÓN DEBIDAMENTE MOTIVADA, EL PROCEDIMIENTO ADMINISTRATIVO- DISCIPLINARIO POR LA COMISIÓN DE INFRACCIONES GRAVES Y MUY GRAVES, SEGÚN CORRESPONDA.', 'ART. 48', '177984'),
    (785, 'SUB-0785', 'SBM2', 'CONSTITUYE UNA FUNCIÓN DE LOS ÓRGANOS DE DECISIÓN DEL SISTEMA DISCIPLINARIO:', 'EVALUAR LAS INVESTIGACIONES REALIZADAS POR LOS ÓRGANOS DE INVESTIGACIÓN POR LA COMISIÓN DE INFRACCIONES GRAVES Y MUY GRAVES, SEGÚN CORRESPONDA.', 'ART. 48', '177985'),
    (786, 'SUB-0786', 'SBM2', 'CONSTITUYE UNA FUNCIÓN DE LOS ÓRGANOS DE DECISIÓN DEL SISTEMA DISCIPLINARIO:', 'ATENDER EL PEDIDO DE INFORME ORAL QUE PUDIESE EFECTUAR EL INVESTIGADO, SEÑALANDO LUGAR, FECHA Y HORA.', 'ART. 48', '177986'),
    (787, 'SUB-0787', 'SBM2', 'CONSTITUYE UNA FUNCIÓN DE LOS ÓRGANOS DE DECISIÓN DEL SISTEMA DISCIPLINARIO:', 'RECIBIR EL INFORME ELABORADO POR EL ÓRGANO DE INVESTIGACIÓN, PONIENDO EN CONOCIMIENTO DE TAL HECHO AL INVESTIGADO.', 'ART. 48', '177987'),
    (788, 'SUB-0788', 'SBM2', 'ES COMPETENTE PARA RESOLVER EN PRIMERA INSTANCIA LOS PROCEDIMIENTOS ADMINISTRATIVO- DISCIPLINARIOS INVESTIGADOS POR LA OFICINA DE ASUNTOS INTERNOS POR LA COMISIÓN DE INFRACCIONES GRAVES Y MUY GRAVES:', 'EL INSPECTOR GENERAL DE LA POLICÍA NACIONAL DEL PERÚ.', 'ART. 47', '177988'),
    (789, 'SUB-0789', 'SBM2', 'ES COMPETENTE PARA RESOLVER EN PRIMERA INSTANCIA LOS PROCEDIMIENTOS ADMINISTRATIVOS- DISCIPLINARIOS POR LA COMISIÓN DE INFRACCIONES GRAVES Y MUY GRAVES, CONSIDERANDO EL LUGAR DONDE SE COMETIÓ LA INFRACCIÓN:', 'LA INSPECTORÍA DESCENTRALIZADA DE LA POLICÍA NACIONAL DEL PERÚ.', 'ART. 47', '177989'),
    (790, 'SUB-0790', 'SBM2', 'CONSTITUYE UNA FUNCIÓN DE LOS ÓRGANOS DE INVESTIGACIÓN DEL SISTEMA DISCIPLINARIO:', 'PONER EN CONOCIMIENTO DE LA AUTORIDAD COMPETENTE LA EXISTENCIA DE INDICIOS RAZONABLES QUE HAGAN PRESUMIR LA COMISIÓN DE UN DELITO, SIN PERJUICIO DE LA INVESTIGACIÓN DISCIPLINARIA CORRESPONDIENTE.', 'ART. 46', '177990'),
    (791, 'SUB-0791', 'SBM2', 'CONSTITUYE UNA FUNCIÓN DE LOS ÓRGANOS DE INVESTIGACIÓN DEL SISTEMA DISCIPLINARIO: Ley N° 30714 - Régimen Disciplinario PNP', 'FORMULAR EL INFORME ADMINISTRATIVO-DISCIPLINARIO CORRESPONDIENTE RECOMENDANDO LAS ACCIONES O SANCIONES QUE CORRESPONDAN.', 'ART. 46', '177991'),
    (792, 'SUB-0792', 'SBM2', 'CONSTITUYE UNA FUNCIÓN DE LOS ÓRGANOS DE INVESTIGACIÓN DEL SISTEMA DISCIPLINARIO:', 'DISPONER O LEVANTAR LAS MEDIDAS PREVENTIVAS A LAS QUE SE REFIERE LA PRESENTE NORMA.', 'ART. 46', '177992'),
    (793, 'SUB-0793', 'SBM2', 'CONSTITUYE UNA FUNCIÓN DE LOS ÓRGANOS DE INVESTIGACIÓN DEL SISTEMA DISCIPLINARIO:', 'INVESTIGAR EN EL MARCO DEL PROCEDIMIENTO ADMINISTRATIVO-DISCIPLINARIO LOS HECHOS EN LOS CUALES SE ENCUENTRE INVOLUCRADO EL PERSONAL POLICIAL, QUE CONSTITUYAN INFRACCIONES GRAVES O MUY GRAVES TIPIFICADAS EN LA PRESENTE LEY.', 'ART. 46', '177993'),
    (794, 'SUB-0794', 'SBM2', 'CONSTITUYE UNA FUNCIÓN DE LOS ÓRGANOS DE INVESTIGACIÓN DEL SISTEMA DISCIPLINARIO:', 'EMITIR Y NOTIFICAR LAS RESOLUCIONES DE INICIO DEL PROCEDIMIENTO ADMINISTRATIVO-DISCIPLINARIO.', 'ART. 46', '177994'),
    (795, 'SUB-0795', 'SBM2', 'CONSTITUYE UNA FUNCIÓN DE LOS ÓRGANOS DE INVESTIGACIÓN DEL SISTEMA DISCIPLINARIO:', 'REALIZAR ACCIONES PREVIAS PARA EL ACOPIO DE INDICIOS Y/O EVIDENCIAS QUE SUSTENTEN EL INICIO O NO DEL PROCEDIMIENTO ADMINISTRATIVO-DISCIPLINARIO.', 'ART. 46', '177995'),
    (796, 'SUB-0796', 'SBM2', 'ES COMPETENTE PARA REALIZAR INVESTIGACIONES CUANDO SE ENCUENTREN INVOLUCRADOS OFICIALES GENERALES DE LA POLICÍA NACIONAL DEL PERÚ, POR LA COMISIÓN DE CUALQUIER TIPO DE INFRACCIÓN:', 'LA OFICINA GENERAL DE INTEGRIDAD INSTITUCIONAL A TRAVÉS DE LA OFICINA DE ASUNTOS INTERNOS', 'ART. 45', '177997'),
    (797, 'SUB-0797', 'SBM2', 'PARA SER DESIGNADO MIEMBRO DEL TRIBUNAL DE DISCIPLINA POLICIAL SE REQUIERE:', 'CONTAR CON TÍTULO PROFESIONAL DE ABOGADO Y COLEGIATURA HÁBIL.', 'ART. 44', '177999'),
    (798, 'SUB-0798', 'SBM2', 'EL PLAZO DE LA ETAPA DE INVESTIGACIÓN PARA LAS INFRACCIONES GRAVES SERÁ DE ...:', 'VEINTE DÍAS HÁBILES.', 'ART. 65', '178001'),
    (799, 'SUB-0799', 'SBM2', 'EL PLAZO ORDINARIO DE LA ETAPA DE INVESTIGACIÓN PARA LAS INFRACCIONES MUY GRAVES SERÁ DE ...:', '35 DÍAS HÁBILES.', 'ART. 66', '178002'),
    (800, 'SUB-0800', 'SBM2', 'LA FACULTAD PARA EL INICIO DEL PROCEDIMIENTO ADMINISTRATIVO-DISCIPLINARIO PARA LA DETERMINACIÓN DE LA EXISTENCIA DE INFRACCIONES DISCIPLINARIAS TIPIFICADAS EN LA PRESENTE LEY, PRESCRIBE POR EL TRANSCURSO DE LOS SIGUIENTES PLAZOS:', 'POR INFRACCIONES MUY GRAVES, A LOS 4 AÑOS DE COMETIDAS.', 'ART. 68', '178003')
)
INSERT INTO pregunta (
  banco_id, materia_id, codigo_pregunta, numero_oficial, enunciado, contexto, ubicacion_fuente, codigo_fuente, tipo_pregunta, dificultad_estimada, frecuencia_examen, tema_especifico, subtema, score_importancia, activo, revisada, creado_at, actualizado_at
)
SELECT
  b.id, m.id, d.codigo_pregunta, d.numero_oficial, d.enunciado,
  ('RESPUESTA: ' || d.respuesta_texto || ' | UBICACION: ' || COALESCE(d.ubicacion,'') || ' | CODIGO_FUENTE: ' || COALESCE(d.codigo_fuente,'')) AS contexto,
  NULLIF(d.ubicacion,''), NULLIF(d.codigo_fuente,''),
  'multiple_choice', 'medio', 'media', 'Banco Suboficiales PDF',
  COALESCE(NULLIF(d.ubicacion,''), 'Sin ubicacion'),
  70, TRUE, TRUE, NOW(), NOW()
FROM data d
JOIN banco b ON TRUE
JOIN materias m ON m.codigo = d.materia_codigo
WHERE NOT EXISTS (SELECT 1 FROM pregunta p WHERE p.codigo_pregunta = d.codigo_pregunta);

