    ('SUB-0778', 'A', 'DISPONER A LOS ÓRGANOS DE INVESTIGACIÓN LA REALIZACIÓN DE ACCIONES DE INVESTIGACIÓN COMPLEMENTARIAS; EN CASO RESULTE NECESARIO.', FALSE, 1),
    ('SUB-0778', 'B', 'PONER EN CONOCIMIENTO DEL INTERESADO LA RESOLUCIÓN QUE RESUELVE EL PROCEDIMIENTO ADMINISTRATIVO-DISCIPLINARIO.', FALSE, 2),
    ('SUB-0778', 'C', 'CONOCE Y RESUELVE EN APELACIÓN O CONSULTA, LAS ABSOLUCIONES Y SANCIONES DE INFRACCIONES GRAVES Y LEVES, SIEMPRE QUE ESTAS HAYAN SIDO IMPUTADAS CON INFRACCIONES MUY GRAVES EN UN MISMO PROCEDIMIENTO ADMINISTRATIVO DISCIPLINARIO', TRUE, 3),
    ('SUB-0778', 'D', 'PONER EN CONOCIMIENTO DE LA DIRECCIÓN EJECUTIVA DE PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ PARA SU REGISTRO Y EJECUCIÓN CORRESPONDIENTE, LA RESOLUCIÓN, DEBIDAMENTE NOTIFICADA AL INTERESADO, QUE RESUELVE EL PROCEDIMIENTO ADMINISTRATIVO-DISCIPLINARIO.', FALSE, 4),
    ('SUB-0778', 'E', 'INVESTIGAR EN EL MARCO DEL PROCEDIMIENTO ADMINISTRATIVO-DISCIPLINARIO LOS HECHOS EN LOS CUALES SE ENCUENTRE INVOLUCRADO EL PERSONAL POLICIAL, QUE CONSTITUYAN INFRACCIONES GRAVES O MUY GRAVES TIPIFICADAS EN LA PRESENTE LEY.', FALSE, 5),
    ('SUB-0779', 'A', 'RECIBIR EL INFORME ELABORADO POR EL ÓRGANO DE INVESTIGACIÓN, PONIENDO EN CONOCIMIENTO DE TAL HECHO AL INVESTIGADO.', FALSE, 1),
    ('SUB-0779', 'B', 'CONOCER Y RESOLVER LOS RECURSOS DE APELACIÓN INTERPUESTOS CONTRA LAS RESOLUCIONES QUE DISPONEN MEDIDAS PREVENTIVAS POR INFRACCIONES MUY GRAVES EN CASO DE OFICIALES GENERALES.', TRUE, 2),
    ('SUB-0779', 'C', 'ATENDER EL PEDIDO DE INFORME ORAL QUE PUDIESE EFECTUAR EL INVESTIGADO, SEÑALANDO LUGAR, FECHA Y HORA.', FALSE, 3),
    ('SUB-0779', 'D', 'EVALUAR LAS INVESTIGACIONES REALIZADAS POR LOS ÓRGANOS DE INVESTIGACIÓN POR LA COMISIÓN DE INFRACCIONES GRAVES Y MUY GRAVES, SEGÚN CORRESPONDA. Ley N° 30714 - Régimen Disciplinario PNP', FALSE, 4),
    ('SUB-0779', 'E', 'RESOLVER MEDIANTE RESOLUCIÓN DEBIDAMENTE MOTIVADA, EL PROCEDIMIENTO ADMINISTRATIVO- DISCIPLINARIO POR LA COMISIÓN DE INFRACCIONES GRAVES Y MUY GRAVES, SEGÚN CORRESPONDA.', FALSE, 5),
    ('SUB-0780', 'A', 'CONOCER Y RESOLVER EN ÚLTIMA Y DEFINITIVA INSTANCIA LOS RECURSOS DE APELACIÓN CONTRA LAS RESOLUCIONES QUE IMPONEN SANCIONES POR INFRACCIONES MUY GRAVES, ASÍ COMO LAS SANCIONES IMPUESTAS POR EL INSPECTOR GENERAL DE LA POLICÍA NACIONAL DEL PERÚ. ASIMISMO, CONOCE Y RESUELVE LAS RESOLUCIONES EXPEDIDAS POR LOS ÓRGANOS DISCIPLINARIOS COMPETENTES, CONFORME LO ESTABLECE ESTA LEY.', TRUE, 1),
    ('SUB-0780', 'B', 'PONER EN CONOCIMIENTO DE LA DIRECCIÓN EJECUTIVA DE PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ PARA SU REGISTRO Y EJECUCIÓN CORRESPONDIENTE, LA RESOLUCIÓN, DEBIDAMENTE NOTIFICADA AL INTERESADO, QUE RESUELVE EL PROCEDIMIENTO ADMINISTRATIVO-DISCIPLINARIO', FALSE, 2),
    ('SUB-0780', 'C', 'PONER EN CONOCIMIENTO DEL INTERESADO LA RESOLUCIÓN QUE RESUELVE EL PROCEDIMIENTO ADMINISTRATIVODISCIPLINARIO.', FALSE, 3),
    ('SUB-0780', 'D', 'DISPONER A LOS ÓRGANOS DE INVESTIGACIÓN LA REALIZACIÓN DE ACCIONES DE INVESTIGACIÓN COMPLEMENTARIAS; EN CASO RESULTE NECESARIO.', FALSE, 4),
    ('SUB-0780', 'E', 'RESOLVER MEDIANTE RESOLUCIÓN DEBIDAMENTE MOTIVADA, EL PROCEDIMIENTO ADMINISTRATIVO- DISCIPLINARIO POR LA COMISIÓN DE INFRACCIONES GRAVES Y MUY GRAVES, SEGÚN CORRESPONDA.', FALSE, 5),
    ('SUB-0781', 'A', 'CONOCER Y RESOLVER EN ÚLTIMA Y DEFINITIVA INSTANCIA LOS RECURSOS DE APELACIÓN CONTRA LAS RESOLUCIONES QUE IMPONEN SANCIONES POR INFRACCIONES MUY GRAVES, ASÍ COMO LAS SANCIONES IMPUESTAS POR EL INSPECTOR GENERAL DE LA POLICÍA NACIONAL DEL PERÚ. ASIMISMO CONOCE Y RESUELVE LAS RESOLUCIONES EXPEDIDAS POR LOS ÓRGANOS DISCIPLINARIOS COMPETENTES, CONFORME LO ESTABLECE ESTA LEY.', FALSE, 1),
    ('SUB-0781', 'B', 'CONOCER Y RESOLVER LOS RECURSOS DE APELACIÓN INTERPUESTOS CONTRA LAS RESOLUCIONES QUE DISPONEN MEDIDAS PREVENTIVAS POR INFRACCIONES MUY GRAVES.', FALSE, 2),
    ('SUB-0781', 'C', 'PONER EN CONOCIMIENTO DE LA DIRECCIÓN EJECUTIVA DE PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ PARA SU REGISTRO Y EJECUCIÓN CORRESPONDIENTE, LA RESOLUCIÓN, DEBIDAMENTE NOTIFICADA AL INTERESADO, QUE RESUELVE EL PROCEDIMIENTO ADMINISTRATIVO-DISCIPLINARIO.', TRUE, 3),
    ('SUB-0781', 'D', 'RESOLVER EN CONSULTA LAS RESOLUCIONES QUE NO HAYAN SIDO APELADAS. EN ESTOS CASOS, EL TRIBUNAL PODRÁ APROBAR LAS RESOLUCIONES DE PRIMERA INSTANCIA, AGOTANDO LA VÍA ADMINISTRATIVA, O DECLARAR LA NULIDAD DE LA MISMA, DEBIENDO EN ESTE CASO EL ÓRGANO DE INVESTIGACIÓN EMITIR NUEVO PRONUNCIAMIENTO. LAS SANCIONES DE PASE A LA SITUACIÓN DE RETIRO QUE NO HAYAN SIDO IMPUGNADAS, NO SERÁN REVISADAS EN CONSULTA.', FALSE, 4),
    ('SUB-0781', 'E', 'PONER EN CONOCIMIENTO DE LA AUTORIDAD COMPETENTE LA EXISTENCIA DE INDICIOS RAZONABLES QUE HAGAN PRESUMIR LA COMISIÓN DE UN DELITO, SIN PERJUICIO DE LA INVESTIGACIÓN DISCIPLINARIA CORRESPONDIENTE.', FALSE, 5),
