INSERT INTO alternativa (pregunta_id, letra, texto, es_correcta, orden)
SELECT p.id, d.letra::char(1), d.texto, d.es_correcta, d.orden
FROM data d
JOIN pregunta p ON p.codigo_pregunta = d.codigo_pregunta
ON CONFLICT (pregunta_id, letra) DO UPDATE SET
  texto = EXCLUDED.texto,
  es_correcta = EXCLUDED.es_correcta,
  orden = EXCLUDED.orden;

-- Preguntas 801 a 900
WITH banco AS (
  SELECT id FROM banco_de_pregunta WHERE nombre = 'Banco Suboficiales 2025 Promo 2026 (PDF)' AND version = 'v1.0-pdf' LIMIT 1
), materias AS (
  SELECT id, codigo FROM materia WHERE codigo IN ('SBM1','SBM2','SBM3','SBM4','SBM5')
), data(numero_oficial, codigo_pregunta, materia_codigo, enunciado, respuesta_texto, ubicacion, codigo_fuente) AS (
  VALUES
    (801, 'SUB-0801', 'SBM2', 'LA FACULTAD PARA EL INICIO DEL PROCEDIMIENTO ADMINISTRATIVO - DISCIPLINARIO PARA LA DETERMINACIÓN DE LA EXISTENCIA DE INFRACCIONES DISCIPLINARIAS TIPIFICADAS EN LA PRESENTE LEY, PRESCRIBE POR EL TRANSCURSO DE LOS SIGUIENTES PLAZOS:', 'POR INFRACCIONES GRAVES, A LOS 2 AÑOS DE COMETIDAS.', 'ART. 68', '178004'),
    (802, 'SUB-0802', 'SBM2', 'EL PERSONAL SUSPENDIDO TEMPORALMENTE DEL SERVICIO, NO EJERCERÁ NINGÚN CARGO EN LA POLICÍA NACIONAL DEL PERÚ Y MIENTRAS DURE LA MEDIDA PREVENTIVA PERCIBIRÁ EL ...:', '50% DE LA REMUNERACIÓN CONSOLIDADA.', 'ART. 80', '178005'),
    (803, 'SUB-0803', 'SBM2', 'SE IMPONE CUANDO EL INVESTIGADO SE ENCUENTRA PRIVADO DE SU LIBERTAD, POR MANDATO DEL ÓRGANO JURISDICCIONAL, SIN SENTENCIA CONDENATORIA FIRME. DURANTE EL TIEMPO DE PRIVACIÓN DE LIBERTAD SE INTERRUMPE EL TIEMPO DE SERVICIOS.', 'CESE TEMPORAL DEL EMPLEO.', 'ART. 76', '178006'),
    (804, 'SUB-0804', 'SBM2', 'LA APLICACIÓN DE ESTA MEDIDA CONLLEVA A QUE TEMPORALMENTE EL EFECTIVO POLICIAL SEA ASIGNADO A OTRO CARGO, Y ES DISPUESTO POR EL ESCALÓN SUPERIOR AL QUE PERTENECE O POR LA DIRECCIÓN EJECUTIVA DE PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ. NOS REFERIMOS A ...:', 'SEPARACIÓN TEMPORAL DEL CARGO', 'ART. 74', '178007'),
    (805, 'SUB-0805', 'SBM2', 'SEÑALE UNA MEDIDA PREVENTIVA:', 'CESE TEMPORAL DEL EMPLEO.', 'ART. 73', '178008'),
    (806, 'SUB-0806', 'SBM2', 'SEÑALE UNA MEDIDA PREVENTIVA:', 'SUSPENSIÓN TEMPORAL DEL SERVICIO.', 'ART. 73', '178009'),
    (807, 'SUB-0807', 'SBM2', 'NO CONSTITUYEN DEMÉRITO NI SANCIÓN ADMINISTRATIVA:', 'LA SUSPENSIÓN TEMPORAL DEL SERVICIO.', 'ART. 73', '178010'),
    (808, 'SUB-0808', 'SBM2', 'SON DISPOSICIONES ADMINISTRATIVAS DE CARÁCTER PROVISIONAL, QUE SE IMPONEN POR LA PRESUNTA COMISIÓN DE INFRACCIONES MUY GRAVES EN LOS CASOS PREVISTOS EN LA PRESENTE LEY:', 'MEDIDAS PREVENTIVAS.', 'ART. 73', '178011'),
    (809, 'SUB-0809', 'SBM2', 'NO CONSTITUYEN DEMÉRITO NI SANCIÓN ADMINISTRATIVA:', 'LA SEPARACIÓN TEMPORAL DEL CARGO.', 'ART. 73', '178012'),
    (810, 'SUB-0810', 'SBM2', 'ES LA SEPARACIÓN DEFINITIVA DE LA SITUACIÓN DE ACTIVIDAD QUE IMPONE EL ÓRGANO DISCIPLINARIO COMPETENTE POR LA COMISIÓN DE UNA INFRACCIÓN MUY GRAVE:', 'PASE A LA SITUACIÓN DE RETIRO POR MEDIDA DISCIPLINARIA.', 'ART. 30', '178013'),
    (811, 'SUB-0811', 'SBM2', 'EL PASE A LA SITUACIÓN DE DISPONIBILIDAD POR MEDIDA DISCIPLINARIA, IMPLICA LA DISMINUCIÓN DE ...:', '3 PUNTOS Y 5 DÉCIMAS (3,5) DE LA NOTA ANUAL DE DISCIPLINA POR CADA MES QUE SE MANTUVO FUERA DE LA SITUACIÓN DE ACTIVIDAD. Ley N° 30714 - Régimen Disciplinario PNP', 'ART. 30', '178014'),
    (812, 'SUB-0812', 'SBM2', 'EL PASE A LA SITUACIÓN DE DISPONIBILIDAD POR MEDIDA DISCIPLINARIA ES LA SEPARACIÓN TEMPORAL DE LA SITUACIÓN DE ACTIVIDAD POR UN PERÍODO DE ...:', 'SEIS MESES A 2 AÑOS.', 'ART. 30', '178015'),
    (813, 'SUB-0813', 'SBM2', 'ES LA SEPARACIÓN TEMPORAL DE LA SITUACIÓN DE ACTIVIDAD POR UN PERÍODO DE 6 MESES A 2 AÑOS QUE IMPONE EL ÓRGANO DISCIPLINARIO COMPETENTE POR LA COMISIÓN DE UNA INFRACCIÓN MUY GRAVE:', 'PASE A LA SITUACIÓN DE DISPONIBILIDAD POR MEDIDA DISCIPLINARIA.', 'ART. 30', '178016'),
    (814, 'SUB-0814', 'SBM2', 'CADA DÍA DE SANCIÓN DE RIGOR IMPLICA LA DISMINUCIÓN DE ...:', 'UN PUNTO Y TRES DÉCIMAS (1,3) DE LA NOTA ANUAL DE DISCIPLINA.', 'ART. 30', '178017'),
    (815, 'SUB-0815', 'SBM2', 'ES LA SANCIÓN ESCRITA POR LA COMISIÓN DE INFRACCIONES GRAVES QUE IMPONE EL ÓRGANO DISCIPLINARIO COMPETENTE:', 'SANCIÓN DE RIGOR.', 'ART. 30', '178018'),
    (816, 'SUB-0816', 'SBM2', 'LA SANCIÓN SIMPLE SE EXTIENDE DE:', 'UNO A DIEZ DÍAS.', 'ART. 30', '178019'),
    (817, 'SUB-0817', 'SBM2', 'CADA DÍA DE SANCIÓN SIMPLE IMPLICA LA DISMINUCIÓN DE ...:', 'OCHO DÉCIMAS (0,8) DE PUNTO DE LA NOTA ANUAL DE DISCIPLINA.', 'ART. 30', '178020'),
    (818, 'SUB-0818', 'SBM2', 'ES LA SANCIÓN ESCRITA QUE IMPONE EL SUPERIOR JERÁRQUICO U ÓRGANO DISCIPLINARIO COMPETENTE AL INFRACTOR POR LA COMISIÓN DE INFRACCIONES LEVES:', 'SANCIÓN SIMPLE.', 'ART. 30', '178021'),
    (819, 'SUB-0819', 'SBM2', 'ES LA SANCIÓN ESCRITA QUE IMPONE EL SUPERIOR JERÁRQUICO U ÓRGANO DISCIPLINARIO COMPETENTE AL INFRACTOR POR LA COMISIÓN DE INFRACCIONES LEVES:', 'AMONESTACIÓN.', 'ART. 30', '178022'),
    (820, 'SUB-0820', 'SBM2', 'CONSTITUYE UNA CLASE DE INFRACCIÓN:', 'GRAVE.', 'ART. 28', '178023'),
    (821, 'SUB-0821', 'SBM2', 'CONSTITUYE UNA CLASE DE INFRACCIÓN:', 'MUY GRAVES.', 'ART. 28', '178024'),
    (822, 'SUB-0822', 'SBM2', 'SEGÚN SU GRAVEDAD, LAS INFRACCIONES SE CLASIFICAN EN:', 'LEVES, GRAVES Y MUY GRAVES.', 'ART. 28', '178025'),
    (823, 'SUB-0823', 'SBM2', 'CONSTITUYE EL MEDIO EMPLEADO PARA TRANSMITIR Y RECIBIR ÓRDENES, DISPOSICIONES, REQUERIMIENTOS, CONSIGNAS Y DOCUMENTOS EN GENERAL A TRAVÉS DE LA LÍNEA DE COMANDO ESTABLECIDA EN LA ORGANIZACIÓN POLICIAL:', 'EL CONDUCTO REGULAR.', 'ART. 25', '178026'),
    (824, 'SUB-0824', 'SBM2', 'SON ACCIONES U OMISIONES QUE ATENTAN CONTRA LAS OBLIGACIONES Y DEBERES ESTABLECIDOS EN EL ORDENAMIENTO LEGAL DE LA POLICÍA NACIONAL DEL PERÚ, Y ESPECIALMENTE AQUELLAS RELACIONADAS CON LOS BIENES JURÍDICOS PROTEGIDOS POR LA PRESENTE NORMA:', 'LAS INFRACCIONES.', 'ART. 27', '178027'),
    (825, 'SUB-0825', 'SBM2', 'LAS ÓRDENES DEBEN CUMPLIRSE EN EL ...:', 'TIEMPO, LUGAR Y MODO INDICADO POR EL SUPERIOR.', 'ART. 24', '178028'),
    (826, 'SUB-0826', 'SBM2', 'EL CONDUCTO REGULAR ES ...:', 'DE OBSERVANCIA OBLIGATORIA', 'ART. 25', '178029'),
    (827, 'SUB-0827', 'SBM2', 'TODA ORDEN DEBE SER:', 'LÍCITA, LÓGICA, OPORTUNA, CLARA, COHERENTE Y PRECISA.', 'ART. 23', '178030'),
    (828, 'SUB-0828', 'SBM2', 'SE EJERCITA MEDIANTE ÓRDENES VERBALES O ESCRITAS QUE DEBEN SER CUMPLIDAS A CABALIDAD DENTRO DEL MARCO LEGAL:', 'EL COMANDO.', 'ART. 23', '178031'),
    (829, 'SUB-0829', 'SBM2', 'LA FACULTAD DISCIPLINARIA SANCIONADORA PARA INFRACCIONES GRAVES Y MUY GRAVES, CORRESPONDE A ...:', 'INSPECTORÍA DESCENTRALIZADA COMPETENTE, A LA INSPECTORÍA MACRO REGIONAL, A LA INSPECTORÍA GENERAL DE LA POLICÍA NACIONAL DEL PERÚ Y AL TRIBUNAL DE DISCIPLINA POLICIAL.', 'ART. 22', '178032'),
    (830, 'SUB-0830', 'SBM2', 'EL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ ESTÁ FACULTADO PARA SANCIONAR AL PERSONAL DE IGUAL GRADO BAJO SU ...:', 'COMANDO.', 'ART. 22', '178033'),
    (831, 'SUB-0831', 'SBM2', 'EL EJERCICIO DEL MANDO Y COMANDO ES ...:', 'IRRENUNCIABLE.', 'ART. 21', '178034'),
    (832, 'SUB-0832', 'SBM2', 'LA FACULTAD DISCIPLINARIA SANCIONADORA PARA INFRACCIONES LEVES, ES INHERENTE AL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ EN SITUACIÓN DE ...:', 'ACTIVIDAD.', 'ART. 22', '178035'),
    (833, 'SUB-0833', 'SBM2', 'DEBIDO A LA NATURALEZA DE LA FUNCIÓN O MISIÓN POLICIAL, EL COMANDO DE LAS UNIDADES Y DEPENDENCIAS POLICIALES DEBE SER ASUMIDO POR PERSONAL POLICIAL DE ARMAS, AUN CUANDO SE ENCUENTRE PRESENTE PERSONAL DE SERVICIOS DE MAYOR GRADO O ANTIGÜEDAD. EL PÁRRAFO ANTERIOR SE REFIERE A ...:', 'EJERCICIO DEL COMANDO.', 'ART. 20', '178036'),
    (834, 'SUB-0834', 'SBM2', 'ES LA FACULTAD QUE TIENE EL SUPERIOR EN SITUACIÓN DE ACTIVIDAD PARA DIRIGIRSE A UN SUBORDINADO, EN RAZÓN DE SU CATEGORÍA, JERARQUÍA, GRADO Y ANTIGÜEDAD E IMPARTIR ÓRDENES DE CARÁCTER GENERAL:', 'EL MANDO', 'ART. 19', '178037'),
    (835, 'SUB-0835', 'SBM2', 'RESPECTO A LA SUBORDINACIÓN SELECCIONE LA RESPUESTA CORRECTA: Ley N° 30714 - Régimen Disciplinario PNP', 'EXISTE SUBORDINACIÓN HACIA EL SUPERIOR EN RAZÓN DEL GRADO, ANTIGÜEDAD O CARGO.', 'ART. 16', '178038'),
    (836, 'SUB-0836', 'SBM2', 'EL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ DEBE MANTENER CORDIALES RELACIONES CON LOS FUNCIONARIOS PÚBLICOS Y CON LOS REPRESENTANTES DE LAS INSTITUCIONES PRIVADAS. EL ENUNCIADO CORRESPONDE A ...:', 'SIGNOS Y EXPRESIONES DE RESPETO.', 'ART. 15', '178039'),
    (837, 'SUB-0837', 'SBM2', 'LOS JEFES DE LAS UNIDADES POLICIALES AL ASUMIR EL CARGO, PRESENTARÁN SU SALUDO EN FORMA PERSONAL O POR ESCRITO, A LAS AUTORIDADES QUE CORRESPONDAN. EL ENUNCIADO CORRESPONDE A ...:', 'SIGNOS Y EXPRESIONES DE RESPETO.', 'ART. 15', '178040'),
    (838, 'SUB-0838', 'SBM2', 'LA PRESENTACIÓN Y RECONOCIMIENTO PARA EL EJERCICIO DEL COMANDO O DESEMPEÑO DEL CARGO SON OBLIGATORIOS, Y SE EJECUTARÁN EN CEREMONIA CONFORME A LO DISPUESTO EN EL REGLAMENTO RESPECTIVO. EL ENUNCIADO CORRESPONDE A ...:', 'SIGNOS Y EXPRESIONES DE RESPETO.', 'ART. 15', '178041'),
    (839, 'SUB-0839', 'SBM2', 'LA MANERA DE PRESENTARSE AL SUPERIOR DEBE SER CON PULCRITUD EN EL VESTIR Y BUENOS MODALES. EL PERSONAL ESTÁ OBLIGADO A USAR EL UNIFORME O EL TRAJE DE CIVIL CON SOBRIEDAD, DECORO, ASEO Y CORRECCIÓN. EL ENUNCIADO CORRESPONDE A ...:', 'SIGNOS Y EXPRESIONES DE RESPETO.', 'ART. 15', '178042'),
    (840, 'SUB-0840', 'SBM2', 'EL SALUDO REGLAMENTARIO AL SUPERIOR ES OBLIGATORIO EN TODO LUGAR O CIRCUNSTANCIA, ESTE TIENE EL DEBER DE CONTESTARLO. EL SUBORDINADO ANTE LA PRESENCIA DEL SUPERIOR DEBE PONERSE DE PIE Y ADOPTAR LA POSICIÓN DE ATENCIÓN. ENTRE PERSONAL DE IGUAL GRADO, EL MENOS ANTIGUO ESTÁ OBLIGADO A SALUDAR REGLAMENTARIAMENTE; EN CASO DE DUDA, CUALQUIERA DE ELLOS PUEDE ANTICIPARSE, DEMOSTRANDO ASÍ SU CORTESÍA, DISCIPLINA Y EDUCACIÓN. EL ENUNCIADO CORRESPONDE A ...:', 'SIGNOS Y EXPRESIONES DE RESPETO.', 'ART. 15', '178043'),
    (841, 'SUB-0841', 'SBM2', 'SON AQUELLOS QUE NORMAN LAS RELACIONES INTERNAS Y EXTERNAS ENTRE LOS MIEMBROS DE LA INSTITUCIÓN Y DEMÁS AUTORIDADES, Y CON LA CIUDADANÍA EN GENERAL:', 'SIGNOS Y EXPRESIONES DE RESPETO.', 'ART. 15', '178044'),
    (842, 'SUB-0842', 'SBM2', 'EL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ SANCIONADO CON RESOLUCIÓN FIRME POR LA COMISIÓN DE INFRACCIÓN GRAVE O MUY GRAVE QUE AFECTE LA FUNCIÓN QUE VENÍA DESEMPEÑANDO, NO PODRÁ CONTINUAR NI VOLVER A SER ASIGNADO AL CARGO QUE OCUPABA AL MOMENTO DE COMETER LA INFRACCIÓN O EN FUNCIONES ANÁLOGAS EN OTRA UNIDAD, POR UN PERÍODO DE ...:', '5 AÑOS.', 'ART. 13', '178045'),
    (843, 'SUB-0843', 'SBM2', 'EL PERSONAL POLICIAL BRINDA UN TRATO CORTÉS Y RESPETUOSO AL CIUDADANO:', 'TRATO DEBIDO.', 'ART. 7', '178046'),
    (844, 'SUB-0844', 'SBM2', 'SON LOS MANDATOS O REGLAS DE CUMPLIMIENTO OBLIGATORIO DEL PERSONAL POLICIAL DENTRO Y FUERA DEL SERVICIO, GARANTIZA EL RESPETO DE LOS BIENES JURÍDICOS PROTEGIDOS:', 'NORMAS DE CONDUCTA.', 'ART. 6', '178047'),
    (845, 'SUB-0845', 'SBM2', 'ES EL CONJUNTO DE ACTIVIDADES QUE EJECUTA EL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ EN SITUACIÓN DE ACTIVIDAD PARA EL CUMPLIMIENTO DE LA MISIÓN Y FUNCIONES INSTITUCIONALES, DE ACUERDO A LO ESTIPULADO EN LA CONSTITUCIÓN POLÍTICA DEL PERÚ, LAS LEYES Y REGLAMENTOS.', 'SERVICIO POLICIAL.', 'ART. 5', '178048'),
    (846, 'SUB-0846', 'SBM2', 'SU OBSERVANCIA GENERA CONFIANZA Y RESPETO EN LAS PERSONAS, LA SOCIEDAD, LA PATRIA Y LA INSTITUCIÓN:', 'ÉTICA POLICIAL.', 'ART. 5', '178049'),
    (847, 'SUB-0847', 'SBM2', 'TAMBIÉN SE APLICARÁ AL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ EN SITUACIÓN DE RETIRO, SIEMPRE QUE LAS PRESUNTAS INFRACCIONES SE HAYAN COMETIDO MIENTRAS SE ENCONTRABA EN SITUACIÓN DE ACTIVIDAD O DISPONIBILIDAD. NOS REFERIMOS A ...:', 'EL ALCANCE DE LA LEY 30714.', 'ART. 4', '178050'),
    (848, 'SUB-0848', 'SBM2', 'COMPRENDE AL PERSONAL POLICIAL EN SITUACIÓN DE ACTIVIDAD Y DISPONIBILIDAD. NOS REFERIMOS A ...:', 'EL ALCANCE DE LA LEY 30714.', 'ART. 4', '178051'),
    (849, 'SUB-0849', 'SBM2', 'ESTABLECER LAS NORMAS Y PROCEDIMIENTOS ADMINISTRATIVO-DISCIPLINARIOS DESTINADOS A PREVENIR, REGULAR Y SANCIONAR LAS INFRACCIONES COMETIDAS POR EL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ, CONSTITUYE:', 'EL OBJETO DE LA LEY 30714.', 'ART. 2', '178052'),
    (850, 'SUB-0850', 'SBM2', 'SON APLICABLES LAS DISPOSICIONES SANCIONADORAS VIGENTES EN EL MOMENTO DE INCURRIR EL INFRACTOR EN LA CONDUCTA A SANCIONAR, SALVO QUE LAS POSTERIORES LE SEAN MÁS FAVORABLES. CORRESPONDE AL PRINCIPIO DE:', 'IRRETROACTIVIDAD.', 'ART. 1', '178053'),
    (851, 'SUB-0851', 'SBM2', 'MEDIANTE EL CUAL NADIE DEBE SER DISCRIMINADO POR MOTIVO DE ORIGEN, RAZA, SEXO, IDIOMA, RELIGIÓN, OPINIÓN, CONDICIÓN ECONÓMICA O DE CUALQUIERA OTRA ÍNDOLE. CORRESPONDE AL PRINCIPIO DE:', 'IGUALDAD.', 'ART. 1', '178054'),
    (852, 'SUB-0852', 'SBM2', 'LA RESPONSABILIDAD DEBE RECAER EN QUIEN REALIZA LA CONDUCTA OMISIVA O ACTIVA CONSTITUTIVA DE INFRACCIÓN SANCIONABLE. CORRESPONDE AL PRINCIPIO DE:', 'CAUSALIDAD.', 'ART. 1', '178055'),
    (853, 'SUB-0853', 'SBM2', 'LAS ENTIDADES DEBEN PRESUMIR QUE LOS ADMINISTRADOS HAN ACTUADO APEGADOS A SUS DEBERES MIENTRAS NO CUENTEN CON EVIDENCIA EN CONTRARIO. CORRESPONDE AL PRINCIPIO DE:', 'PRESUNCIÓN DE LICITUD', 'ART. 1', '178056'),
    (854, 'SUB-0854', 'SBM2', 'EL SUPERIOR Y LOS ÓRGANOS DISCIPLINARIOS DEBEN CUMPLIR SU ACTUACIÓN DENTRO DE LOS PLAZOS ESTABLECIDOS, EVITANDO ACTUACIONES INNECESARIAS QUE DIFICULTEN SU DESENVOLVIMIENTO. CORRESPONDE AL PRINCIPIO DE:', 'CELERIDAD.', 'ART. 1', '178057'),
    (855, 'SUB-0855', 'SBM2', 'LA RESPONSABILIDAD ADMINISTRATIVA ES SUBJETIVA, SALVO LOS CASOS EN QUE POR LEY SE DISPONGA LA RESPONSABILIDAD ADMINISTRATIVA OBJETIVA. CORRESPONDE AL PRINCIPIO DE:', 'CULPABILIDAD.', 'ART. 1', '178058'),
    (856, 'SUB-0856', 'SBM2', 'EL SUPERIOR Y LOS ÓRGANOS DISCIPLINARIOS ACTÚAN SIN NINGUNA CLASE DE DISCRIMINACIÓN O FAVORITISMO ENTRE EL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ OTORGÁNDOLES TRATAMIENTO OBJETIVO Y TUTELA IGUALITARIA FRENTE AL PROCEDIMIENTO, EN ATENCIÓN A LOS BIENES JURÍDICOS PROTEGIDOS POR LA PRESENTE NORMA. CORRESPONDE AL PRINCIPIO DE:', 'IMPARCIALIDAD.', 'ART. 1', '178059'),
    (857, 'SUB-0857', 'SBM2', 'ADECUACIÓN DE LA CONDUCTA A LA INFRACCIÓN DESCRITA Y SANCIONADA POR LA NORMA SIN ADMITIR INTERPRETACIÓN EXTENSIVA O POR ANALOGÍA. CORRESPONDE AL PRINCIPIO DE:', 'TIPICIDAD.', 'ART. 1', '178060'),
    (858, 'SUB-0858', 'SBM2', 'EL PERSONAL QUE CONOZCA DE UNA INVESTIGACIÓN ADMINISTRATIVO-DISCIPLINARIA O SEA PARTE DE LA MISMA, ESTÁ OBLIGADO A MANTENER RESERVA DEL CONTENIDO DEL PROCEDIMIENTO HASTA SU CULMINACIÓN. CORRESPONDE AL PRINCIPIO DE:', 'RESERVA.', 'ART. 1', '178061'),
    (859, 'SUB-0859', 'SBM2', 'EL CONOCIMIENTO DE LA COMISIÓN DE UNA INFRACCIÓN OBLIGA EL INICIO INMEDIATO DEL PROCEDIMIENTO ADMINISTRATIVO-DISCIPLINARIO CORRESPONDIENTE Y COMPROMETE LA RESPONSABILIDAD DEL SUPERIOR. NOS REFERIMOS AL ...:', 'PRINCIPIO DE INMEDIATEZ.', 'ART. 1', '178062'),
    (860, 'SUB-0860', 'SBM2', 'EL DERECHO A SER NOTIFICADO, CORRESPONDE AL:', 'PRINCIPIO DEL DEBIDO PROCEDIMIENTO.', 'ART. 1', '178063'),
    (861, 'SUB-0861', 'SBM2', 'ACCEDER AL EXPEDIENTE, CORRESPONDE AL:', 'PRINCIPIO DEL DEBIDO PROCEDIMIENTO', 'ART. 1', '178064'),
    (862, 'SUB-0862', 'SBM2', 'EL PROCEDIMIENTO DISCIPLINARIO SANCIONADOR ES INDEPENDIENTE Y DISTINTO DE LOS PROCESOS JURISDICCIONALES CIVILES, PENALES U OTROS; Y ESTÁ ORIENTADA A ESTABLECER LA RESPONSABILIDAD ADMINISTRATIVO-DISCIPLINARIA EN LAS QUE INCURRE EL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ. NOS REFERIMOS AL:', 'PRINCIPIO DE LA AUTONOMÍA DE LA RESPONSABILIDAD ADMINISTRATIVA.', 'ART. 1', '178065'),
    (863, 'SUB-0863', 'SBM2', 'EL PERSONAL DE LA POLICÍA NACIONAL DEL PERÚ, ESTÁ PROHIBIDO DE:', 'PARTICIPAR EN MANIFESTACIONES PÚBLICAS.', 'ART. 12', '178066'),
    (864, 'SUB-0864', 'SBM2', 'PARA SER DESIGNADO MIEMBRO DEL TRIBUNAL DE DISCIPLINA POLICIAL SE REQUIERE:', 'TENER ESTUDIOS DE ESPECIALIZACIÓN, YA SEA EN GESTIÓN PÚBLICA, DERECHO CONSTITUCIONAL, ADMINISTRATIVO, PENAL, LABORAL, CIENCIAS POLICIALES, GESTIÓN DE RECURSOS HUMANOS O SIMILARES.', 'ART, 44', '178067'),
    (865, 'SUB-0865', 'SBM2', 'PARA SER DESIGNADO MIEMBRO DEL TRIBUNAL DE DISCIPLINA POLICIAL SE REQUIERE SER OFICIAL GENERAL U OFICIAL SUPERIOR DE LA POLICÍA NACIONAL DEL PERÚ EN SITUACIÓN DE RETIRO CON LA ESPECIALIDAD DE:', 'CONTROL ADMINISTRATIVO-DISCIPLINARIO.', 'ART. 44', '178068'),
    (866, 'SUB-0866', 'SBM2', 'PARA SER DESIGNADO MIEMBRO DEL TRIBUNAL DE DISCIPLINA POLICIAL SE REQUIERE TENER COMPROBADA DOCENCIA UNIVERSITARIA POR EL PERÍODO NO MENOR DE:', '10 AÑOS.', 'ART. 44', '178069'),
    (867, 'SUB-0867', 'SBM2', 'TIENE COMO FUNCIÓN PREPARAR TODO LO NECESARIO PARA QUE EL TRIBUNAL PUEDA CUMPLIR CON SUS FUNCIONES:', 'LA SECRETARÍA TÉCNICA DE LAS SALAS DEL TRIBUNAL.', 'ART. 43', '178070'),
    (868, 'SUB-0868', 'SBM2', 'TIENE COMO FUNCIÓN SERVIR DE ENLACE ENTRE LOS ÓRGANOS DE INVESTIGACIÓN Y EL TRIBUNAL DE DISCIPLINA POLICIAL:', 'LA SECRETARÍA TÉCNICA', 'ART. 43', '178072'),
    (869, 'SUB-0869', 'SBM2', 'CADA SALA DEL TRIBUNAL CONTARÁ CON UNA SECRETARÍA TÉCNICA A CARGO DE UN SECRETARIO TÉCNICO DESIGNADO POR ...:', 'RESOLUCIÓN MINISTERIAL A PROPUESTA DE LA SALA CORRESPONDIENTE.', 'ART. 43', '178073'),
    (870, 'SUB-0870', 'SBM2', 'EL PRESIDENTE DEL TRIBUNAL DE DISCIPLINA POLICIAL ES DESIGNADO POR EL MINISTRO DEL INTERIOR POR UN PERÍODO DE:', '3 AÑOS.', 'ART. 42', '178074'),
    (871, 'SUB-0871', 'SBM2', 'CADA SALA DEL TRIBUNAL DE DISCIPLINA POLICIAL CONTARÁ CON UNA ...:', 'SECRETARÍA TÉCNICA.', 'ART. 43', '178075'),
    (872, 'SUB-0872', 'SBM2', 'ES EL ÓRGANO DE GESTIÓN PARA LA ADMINISTRACIÓN Y FUNCIONAMIENTO DEL TRIBUNAL DE DISCIPLINA POLICIAL:', 'LA PRESIDENCIA DEL TRIBUNAL DE DISCIPLINA POLICIAL.', 'ART. 42', '178076'),
    (873, 'SUB-0873', 'SBM2', 'EL PRESIDENTE DEL TRIBUNAL DE DISCIPLINA POLICIAL ES DESIGNADO POR:', 'MINISTRO DEL INTERIOR.', 'ART. 42', '178077'),
    (874, 'SUB-0874', 'SBM2', 'NO PODRÁ DESIGNARSE COMO MIEMBRO DE SALA DEL TRIBUNAL DE DISCIPLINA POLICIAL, AL PERSONAL POLICIAL EN SITUACIÓN DE:', 'ACTIVIDAD.', 'ART. 41', '178078'),
    (875, 'SUB-0875', 'SBM2', 'LA FUNCIÓN DE MIEMBRO DE SALA DEL TRIBUNAL DE DISCIPLINA POLICIAL, ES:', 'A TIEMPO COMPLETO', 'ART. 41', '178079'),
    (876, 'SUB-0876', 'SBM2', 'CADA SALA ESTARÁ COMPUESTA POR 3 VOCALES, CUYA DESIGNACIÓN Y CONFORMACIÓN SE DISPONE POR RESOLUCIÓN MINISTERIAL POR UN PERÍODO DE 3 AÑOS, DEBIENDO SER INTEGRADA POR AL MENOS UN OFICIAL GENERAL U OFICIAL SUPERIOR EN SITUACIÓN DE RETIRO, QUE CUENTE CON LA ESPECIALIDAD DE CONTROL ADMINISTRATIVO-DISCIPLINARIO, DE ACUERDO A LO ESTABLECIDO POR EL:', 'DECRETO LEGISLATIVO 1291.', 'ART. 41', '178080'),
    (877, 'SUB-0877', 'SBM2', 'EL PRESIDENTE DE CADA UNA DE LAS SALAS DEL TRIBUNAL DE DISCIPLINA POLICIAL SERÁ ELEGIDO POR LOS INTEGRANTES DE LA SALA RESPECTIVA, POR EL PERÍODO DE:', '1 AÑO.', 'ART. 41', '178081'),
    (878, 'SUB-0878', 'SBM2', 'CADA SALA DEL TRIBUNAL DE DISCIPLINA POLICIAL ESTARÁ COMPUESTA POR 3 VOCALES, CUYA DESIGNACIÓN Y CONFORMACIÓN SE DISPONE POR RESOLUCIÓN MINISTERIAL POR UN PERÍODO DE 3 AÑOS, DEBIENDO SER INTEGRADA POR AL MENOS UN OFICIAL GENERAL U OFICIAL SUPERIOR EN SITUACIÓN DE RETIRO, QUE CUENTE CON LA ESPECIALIDAD DE:', 'CONTROL ADMINISTRATIVO-DISCIPLINARIO.', 'ART. 41', '178082'),
    (879, 'SUB-0879', 'SBM2', 'LA DESIGNACIÓN DE LOS VOCALES DE LA SALA DEL TRIBUNAL DE DISCIPLINA POLICIAL, SE FORMALIZA CON:', 'RESOLUCIÓN MINISTERIAL', 'ART. 41', '178083'),
    (880, 'SUB-0880', 'SBM2', 'CADA SALA DEL TRIBUNAL DE DISCIPLINA POLICIAL ESTARÁ COMPUESTA POR 3 VOCALES, CUYA DESIGNACIÓN Y CONFORMACIÓN SE DISPONE POR RESOLUCIÓN MINISTERIAL POR UN PERÍODO DE:', '3 AÑOS.', 'ART. 41', '178084'),
    (881, 'SUB-0881', 'SBM2', 'EL TRIBUNAL DE DISCIPLINA POLICIAL TIENE SU SEDE PRINCIPAL EN:', 'LA CAPITAL DE LA REPÚBLICA.', 'ART. 41', '178085'),
    (882, 'SUB-0882', 'SBM2', '¿POR CUÁNTOS VOCALES ESTA CONFORMADO CADA SALA DEL TRIBUNAL DE DISCIPLINA POLICIAL?', '3 VOCALES.', 'ART. 41', '178086'),
    (883, 'SUB-0883', 'SBM2', 'EL TRIBUNAL DE DISCIPLINA POLICIAL PARA EL EJERCICIO DE SUS FUNCIONES CUENTA CON AUTONOMÍA:', 'TÉCNICA Y FUNCIONAL.', 'ART. 41', '178087'),
    (884, 'SUB-0884', 'SBM2', 'ES LA ÚLTIMA INSTANCIA ADMINISTRATIVA EN EL PROCEDIMIENTO DISCIPLINARIO INICIADO POR INFRACCIONES MUY GRAVES:', 'EL TRIBUNAL DE DISCIPLINA POLICIAL', 'ART. 41', '178088'),
    (885, 'SUB-0885', 'SBM2', 'EL TRIBUNAL DE DISCIPLINA POLICIAL ES LA ÚLTIMA INSTANCIA ADMINISTRATIVA EN EL PROCEDIMIENTO DISCIPLINARIO INICIADO POR INFRACCIONES:', 'MUY GRAVES.', 'ART. 41', '178089'),
    (886, 'SUB-0886', 'SBM2', '¿DE QUIÉN DEPENDE EL TRIBUNAL DE DISCIPLINA POLICIAL?', 'DEPENDE DEL MINISTRO DEL INTERIOR.', 'ART. 41', '178090'),
    (887, 'SUB-0887', 'SBM2', 'CONSTITUYE UN IMPEDIMENTO PARA INTERVENIR COMO INTEGRANTE DE LOS ÓRGANOS DEL SISTEMA DISCIPLINARIO:', 'EXISTENCIA DE ENEMISTAD MANIFIESTA CON EL INVESTIGADO O DENUNCIANTE.', 'ART. 40', '178091'),
    (888, 'SUB-0888', 'SBM2', 'CONSTITUYE UN IMPEDIMENTO PARA INTERVENIR COMO INTEGRANTE DE LOS ÓRGANOS DEL SISTEMA DISCIPLINARIO:', 'SER DEUDOR, ACREEDOR, FIADOR DEL INVESTIGADO O DEL DENUNCIANTE, O TENER INTERESES COMUNES CON ESTOS ÚLTIMOS.', 'ART. 40', '178092'),
    (889, 'SUB-0889', 'SBM2', 'CONSTITUYE UN IMPEDIMENTO PARA INTERVENIR COMO INTEGRANTE DE LOS ÓRGANOS DEL SISTEMA DISCIPLINARIO:', 'SER DENUNCIANTE DE LOS HECHOS O HABER SIDO DENUNCIADO ANTES POR ALGUNO DE LOS INVESTIGADOS O DENUNCIANTES.', 'ART. 40 Ley N° 30714 - Régimen Disciplinario PNP', '178093'),
    (890, 'SUB-0890', 'SBM2', 'CONSTITUYE UN IMPEDIMENTO PARA INTERVENIR COMO INTEGRANTE DE LOS ÓRGANOS DEL SISTEMA DISCIPLINARIO:', 'HABER PARTICIPADO EN UNA INVESTIGACIÓN POLICIAL CONTRA EL INVESTIGADO O DENUNCIANTE.', 'ART. 40', '178094'),
    (891, 'SUB-0891', 'SBM2', 'CONSTITUYE UN IMPEDIMENTO PARA INTERVENIR COMO INTEGRANTE DE LOS ÓRGANOS DEL SISTEMA DISCIPLINARIO:', 'PARENTESCO CON EL PERSONAL SUJETO A INVESTIGACIÓN, CON EL DENUNCIANTE O CON LOS MIEMBROS DEL MISMO ÓRGANO DISCIPLINARIO, EN CALIDAD DE CÓNYUGE, CONVIVIENTE O HASTA EL CUARTO GRADO DE CONSANGUINIDAD O SEGUNDO GRADO DE AFINIDAD.', 'ART. 40', '178095'),
    (892, 'SUB-0892', 'SBM2', '¿QUÉ ÓRGANO DISCIPLINARIO ES COMPETENTE PARA RESOLVER LAS QUEJAS POR DEFECTO DE TRAMITACIÓN FORMULADAS CONTRA EL ÓRGANO DE PRIMERA INSTANCIA?', 'LA INSPECTORÍA MACRO REGIONAL.', 'ART. 39', '178096'),
    (893, 'SUB-0893', 'SBM2', '¿QUÉ ÓRGANO DISCIPLINARIO ES COMPETENTE EN SEGUNDA INSTANCIA PARA EL CASO DE INFRACCIONES GRAVES SANCIONADAS POR LAS INSPECTORÍAS DESCENTRALIZADAS?', 'LA INSPECTORÍA MACRO REGIONAL.', 'ART. 39', '178097'),
    (894, 'SUB-0894', 'SBM2', '¿QUÉ ÓRGANO DISCIPLINARIO ES COMPETENTE PARA EL CASO DE INFRACCIONES GRAVES Y MUY GRAVES, SANCIONADAS POR LAS INSPECTORÍAS DESCENTRALIZADAS O EL INSPECTOR GENERAL DE LA POLICÍA NACIONAL DEL PERÚ?', 'EL TRIBUNAL DE DISCIPLINA POLICIAL.', 'ART. 39', '178098'),
    (895, 'SUB-0895', 'SBM2', 'CONSTITUYE UN ÓRGANO DE DECISIÓN EN SEGUNDA INSTANCIA, POR LA COMISIÓN DE INFRACCIONES GRAVES:', 'LA INSPECTORÍA MACRO REGIONAL.', 'ART. 39', '178099'),
    (896, 'SUB-0896', 'SBM2', 'CONSTITUYE UN ÓRGANO DE DECISIÓN EN SEGUNDA INSTANCIA, POR LA COMISIÓN DE INFRACCIONES GRAVES Y MUY GRAVES:', 'EL TRIBUNAL DE DISCIPLINA POLICIAL.', 'ART. 39', '178100'),
    (897, 'SUB-0897', 'SBM2', '¿SI DENTRO DE LA ETAPA DE DECISIÓN POR LA COMISIÓN DE INFRACCIONES MUY GRAVES, SE HA INCLUIDO EN EL EXPEDIENTE CORRESPONDIENTE, LA IMPUTACIÓN POR HECHOS CONSIDERADOS COMO INFRACCIÓN GRAVE O LEVE, QUÉ ÓRGANO DISCIPLINARIO APLICARÁ LA SANCIÓN QUE CORRESPONDA?', 'EL TRIBUNAL DE DISCIPLINA POLICIAL.', 'ART. 39', '178101'),
    (898, 'SUB-0898', 'SBM2', 'ÓRGANO DISCIPLINARIO COMPETENTE POR LA COMISIÓN DE INFRACCIONES GRAVES Y MUY GRAVES LA CUAL EVALÚA LAS INVESTIGACIONES REALIZADAS POR LA OFICINA DE ASUNTOS INTERNOS DEL MINISTERIO DEL INTERIOR, PARA LA IMPOSICIÓN DE LAS SANCIONES QUE CORRESPONDAN, DE SER EL CASO:', 'EL INSPECTOR GENERAL DE LA POLICÍA NACIONAL DEL PERÚ.', 'ART.39', '178102'),
    (899, 'SUB-0899', 'SBM2', 'ÓRGANO DISCIPLINARIO COMPETENTE POR LA COMISIÓN DE INFRACCIONES GRAVES Y MUY GRAVES LA CUAL EVALÚA LAS INVESTIGACIONES REALIZADAS POR LAS OFICINAS DE DISCIPLINA, PARA LA IMPOSICIÓN DE LAS SANCIONES QUE CORRESPONDAN:', 'LA INSPECTORÍA DESCENTRALIZADA.', 'ART. 39', '178103'),
    (900, 'SUB-0900', 'SBM2', 'CONSTITUYE UN ÓRGANO DE DECISIÓN EN PRIMERA INSTANCIA POR LA COMISIÓN DE INFRACCIONES GRAVES Y MUY GRAVES:', 'LA INSPECTORÍA DESCENTRALIZADA COMPETENTE.', 'ART. 39', '178104')
)
INSERT INTO pregunta (
  banco_id, materia_id, codigo_pregunta, numero_oficial, enunciado, contexto, ubicacion_fuente, codigo_fuente, tipo_pregunta, dificultad_estimada, frecuencia_examen, tema_especifico, subtema, score_importancia, activo, revisada, creado_at, actualizado_at
)
SELECT
  b.id, m.id, d.codigo_pregunta, d.numero_oficial, d.enunciado,
  ('RESPUESTA: ' || d.respuesta_texto || ' | UBICACION: ' || COALESCE(d.ubicacion,'') || ' | CODIGO_FUENTE: ' || COALESCE(d.codigo_fuente,'')) AS contexto,
  NULLIF(d.ubicacion,''), NULLIF(d.codigo_fuente,''),
  'multiple_choice', 'medio', 'media', 'Banco Suboficiales PDF',
  COALESCE(NULLIF(d.ubicacion,''), 'Sin ubicacion'),
  70, TRUE, TRUE, NOW(), NOW()
FROM data d
JOIN banco b ON TRUE
JOIN materias m ON m.codigo = d.materia_codigo
WHERE NOT EXISTS (SELECT 1 FROM pregunta p WHERE p.codigo_pregunta = d.codigo_pregunta);

