    ('SUB-0887', 'A', 'SI HA TENIDO INTERVENCIÓN COMO ASESOR, PERITO O TESTIGO EN EL MISMO PROCEDIMIENTO ADMINISTRATIVODISCIPLINARIO, O SI COMO INSTRUCTOR HUBIERE MANIFESTADO PREVIAMENTE SU PARECER SOBRE EL MISMO, DE MODO QUE PUDIERA ENTENDERSE QUE SE HA PRONUNCIADO SOBRE EL ASUNTO, SALVO LA RECTIFICACIÓN DE ERRORES O LA DECISIÓN DEL RECURSO DE RECONSIDERACIÓN.', FALSE, 1),
    ('SUB-0887', 'B', 'EXISTENCIA DE ENEMISTAD MANIFIESTA CON EL INVESTIGADO O DENUNCIANTE.', TRUE, 2),
    ('SUB-0887', 'C', 'SI ES CÓNYUGE, CONVIVIENTE, PARIENTE DENTRO DEL CUARTO GRADO DE CONSANGUINIDAD O SEGUNDO DE AFINIDAD, CON CUALQUIERA DE LAS PARTES O CON SUS REPRESENTANTES.', FALSE, 3),
    ('SUB-0887', 'D', 'SI PERSONALMENTE, O BIEN SU CÓNYUGE, CONVIVIENTE O ALGÚN PARIENTE DENTRO DEL CUARTO GRADO DE CONSANGUINIDAD O SEGUNDO DE AFINIDAD, TUVIERE INTERÉS EN EL PROCEDIMIENTO ADMINISTRATIVO- DISCIPLINARIO QUE SE INVESTIGA O EN OTRO SEMEJANTE, CUYA RESOLUCIÓN PUEDA INFLUIR EN LA SITUACIÓN DE AQUEL.', FALSE, 4),
    ('SUB-0887', 'E', 'CUANDO TUVIERE AMISTAD ÍNTIMA, ENEMISTAD MANIFIESTA O CONFLICTO DE INTERESES OBJETIVO CON CUALQUIERA DE LAS PARTES QUE INTERVIENEN EN EL PROCEDIMIENTO ADMINISTRATIVO-DISCIPLINARIO, QUE SE HAGAN PATENTES MEDIANTE ACTITUDES O HECHOS EVIDENTES EN EL PROCEDIMIENTO.', FALSE, 5),
    ('SUB-0888', 'A', 'SI PERSONALMENTE, O BIEN SU CÓNYUGE, CONVIVIENTE O ALGÚN PARIENTE DENTRO DEL CUARTO GRADO DE CONSANGUINIDAD O SEGUNDO DE AFINIDAD, TUVIERE INTERÉS EN EL PROCEDIMIENTO ADMINISTRATIVO- DISCIPLINARIO QUE SE INVESTIGA O EN OTRO SEMEJANTE, CUYA RESOLUCIÓN PUEDA INFLUIR EN LA SITUACIÓN DE AQUEL.', FALSE, 1),
